(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["image"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-mixed-res-serve"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-res-serve-sec-1\">一 · 事故现场：一个 4K 请求如何拖垮整条批</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-res-serve-sec-2\">二 · 计算量为什么随像素平方增长</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-res-serve-sec-3\">三 · 机制：按 patch 分级，把一条 batch 拆成两条通道</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-res-serve-sec-4\">四 · 适用边界：它治什么，不治什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-res-serve-sec-5\">五 · 失败模式：三个必须提前设计的坑</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-res-serve-sec-6\">六 · 什么时候不该切 patch：一条被长尾拖垮的产线事故</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-res-serve-sec-7\">七 · 请求切分：patch 集合与 SLO 标注的生成</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-res-serve-sec-8\">八 · 分通道入队：分辨率与 SLO 的双键路由</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-res-serve-sec-9\">九 · 通道内采样去噪：两种 kernel 形状的独立执行</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-res-serve-sec-10\">十 · 结果写回与请求级缓冲：拼接前的数据落位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-res-serve-sec-11\">十一 · 拼接、融合与 VAE 解码：尾延迟的最终结算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-res-serve-sec-12\">十二 · 步骤间的耦合与调度失误的传播路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-res-serve-sec-13\">十三 · 快慢通道的边界：patch 分流在什么条件下反噬</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-res-serve-sec-14\">十四 · 逐项拆解 Cost_patch 与 SLO_req 两个核心式</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-res-serve-sec-15\">十五 · 推导的关键一步：从请求级平方增长到 patch 级线性可加</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-res-serve-sec-16\">十六 · 伪代码：patch 切分、通道分配与写回</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-res-serve-sec-17\">十七 · 代价落到资源：延迟、吞吐、显存、带宽</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-res-serve-sec-18\">十八 · 具体例子：一个混合负载请求的调度走位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-res-serve-sec-19\">十九 · 伪代码落到可实现：三个必须写死的工程约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-res-serve-sec-20\">二十 · 补写：patch 代价模型与尾延迟边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-res-serve-sec-21\">二十一 · 请求形态：什么样的负载才配得上 patch 级分流</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-res-serve-sec-22\">二十二 · 长度分布：patch 数量本身就是“序列长度”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-res-serve-sec-23\">二十三 · 并发与批大小：快慢通道的批参数不能同构</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-res-serve-sec-24\">二十四 · 负载不对时会发生什么：三类可观测的退化</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-res-serve-sec-25\">二十五 · 配方落地：把负载特征映射到调度参数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-res-serve-sec-26\">二十六 · 负载配方：混合分辨率请求的适配边界与失效条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-res-serve-sec-27\">二十七 · 硬件档位：按 patch 通道而非请求峰值选卡</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-res-serve-sec-28\">二十八 · 并行拓扑：通道内并行与通道间隔离</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-res-serve-sec-29\">二十九 · 量化方案：按通道的精度分级</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-res-serve-sec-30\">三十 · KV 策略：patch 级缓冲与请求级拼接缓冲分离</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-res-serve-sec-31\">三十一 · 调度参数：通道配额、批大小与尾延迟保护</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-res-serve-sec-32\">三十二 · 可复现配置思路：从约束到参数的落地顺序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-res-serve-sec-33\">三十三 · 配方边界：通道配比、halo 预算与尾延迟闸门</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-res-serve-sec-34\">三十四 · 显存账：patch 缓冲与 halo 的乘性开销</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-res-serve-sec-35\">三十五 · 带宽账：拼接与融合后处理的搬运量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-res-serve-sec-36\">三十六 · 通信账：分离式部署下 patch 的跨节点流动</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-res-serve-sec-37\">三十七 · 功耗与利用率：快慢通道的能效错配</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-res-serve-sec-38\">三十八 · 尾延迟：最慢 patch 支配与队列深度的取舍</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-res-serve-sec-39\">三十九 · 规模上去以后先崩的位置</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-res-serve-sec-40\">四十 · 规模上去以后，先崩的是尾延迟而不是平均吞吐</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-res-serve-sec-41\">四十一 · 精度失败：halo 不足与融合后处理的数值放大</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-res-serve-sec-42\">四十二 · 显存失败：重叠 patch 与请求级缓冲区的叠加占用</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-res-serve-sec-43\">四十三 · 批抖动与路由不均：快慢通道的负载失衡</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-res-serve-sec-44\">四十四 · 尾延迟尖刺：最慢 patch 支配与慢通道排队</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-res-serve-sec-45\">四十五 · 监控面与回滚：可观测信号与降级路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-res-serve-sec-46\">四十六 · 失败模式与诊断：从接缝、尾刺到通道失衡</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-res-serve-sec-47\">四十七 · 对照轴：调度发生在哪一层</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-res-serve-sec-48\">四十八 · 决策表：五类候选与适用条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-res-serve-sec-49\">四十九 · 代价换算：什么时候 patch 化不划算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-res-serve-sec-50\">五十 · 与阶段级流水的分工边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-res-serve-sec-51\">五十一 · 选择流程与切换信号</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-res-serve-sec-52\">五十二 · 分水岭不在算法本身，而在请求形状与尾延迟预算</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:492px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 491.9 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"409.9\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">请求进入后按目标分辨率切分为 patch 集合，标注 SLO 等级</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"409.9\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">patch 调度器按分辨率与 SLO 把 patch 分配到快/慢通道队列</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"409.9\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">快通道用小 batch 低延迟 kernel，慢通道用大 batch 高吞…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"409.9\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">各通道独立采样去噪，patch 结果写回请求级缓冲区</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"409.9\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">全部 patch 完成后拼接、VAE 解码并返回图像</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-mixed-res-serve-sec-1\">一 · 事故现场：一个 4K 请求如何拖垮整条批</h3>\n<p>某扩散服务集群在 2025 年的一次晚高峰出现典型故障：一批 1024×1024 的营销图请求与少量 4096×4096 的海报请求进入同一调度域。服务端按请求整体组 batch，GPU 上同时驻留两类请求。结果是 1024 请求的 p99 延迟被拉长到不可接受的水平，而 4096 请求本身也没有变快——整条 batch 的完成时间由最慢成员决定。运维侧看到的现象是：GPU 利用率不低，吞吐却下降，小请求超时重试进一步放大负载，形成雪崩。根因不是显存不够，也不是 kernel 写错，而是**调度粒度错了**：请求级 batch 把不同分辨率的计算量强行绑在一起。</p>\n<p>这个事故说明了一件事：在 DiT 推理里，分辨率不是“画质参数”，而是**计算量的平方级放大器**。当高分辨率请求与低分辨率请求共享同一个 batch 时，GPU 的 Tensor Core 被大请求的 token 数占满，小请求只能陪跑。混合分辨率补丁调度（mixed-resolution patch scheduling）要解决的正是这个具体问题：让大小请求共享同一张 GPU 而不互相阻塞。它不解决模型质量、不解决量化误差、也不解决单请求内部的采样步数优化——那些属于别的条目。</p>\n\n<h3 id=\"alg-mixed-res-serve-sec-2\">二 · 计算量为什么随像素平方增长</h3>\n<p>DiT 把图像 latent 切成 patch token 序列送入注意力与 GEMM。序列长度与 latent 的空间尺寸成正比，而注意力与大部分 GEMM 的代价随 token 数呈超线性甚至平方关系。给定图像高宽 $H,W$，DiT 计算量可写为：</p>\n<div class=\"formula\">$$C \\propto H\\times W,\\qquad \\text{Cost}_{\\text{patch}} \\propto h\\cdot w\\cdot N_{\\text{step}}$$</div>\n<p>其中 $h,w$ 是单个 patch 的尺寸，$N_{\\text{step}}$ 是该 patch 的采样步数。第一式给出请求级代价随像素面积增长；第二式给出 patch 级代价，它是调度器做分流决策的计价单位。把 4096×4096 与 1024×1024 对比，像素面积相差 16 倍，单请求计算量差距远大于 batch 内其他维度能吸收的范围。工程含义很直接：**混 batch 的 kernel 形状被最大请求支配**，小请求的有效算力利用率被稀释，而大请求因为 batch 里有“轻成员”也拿不到它需要的规整大 batch。两侧同时受损，这就是事故里吞吐与 SLO 一起恶化的机理。</p>\n<p>代价体现在三个维度：延迟上，小请求排队等待大请求的 kernel 完成；吞吐上，Tensor Core 在混合形状下利用率下降；显存上，大请求的激活与 KV 驻留挤压了小请求的并发额度。三者叠加，使请求级调度在混合分辨率负载下失去可预测性。</p>\n\n<h3 id=\"alg-mixed-res-serve-sec-3\">三 · 机制：按 patch 分级，把一条 batch 拆成两条通道</h3>\n<p>算法的核心动作是**把调度粒度从请求下移到 patch**。数据流按顺序执行：请求进入后按目标分辨率切分为 patch 集合，并为每个 patch 标注所属请求的 SLO 等级；patch 调度器按分辨率与 SLO 把 patch 分配到快通道与慢通道两条队列；快通道使用小 batch、低延迟 kernel，慢通道使用大 batch、高吞吐 kernel；两条通道各自独立采样去噪，patch 结果写回请求级缓冲区；全部 patch 完成后拼接、VAE 解码并返回图像。</p>\n<p>伪代码思路如下：</p>\n<ul>\n<li>对请求 $r$：按 $H_r,W_r$ 与目标 patch 尺寸生成 patch 集合 $P_r$，每个 $p$ 携带 $(h_p,w_p,\\text{SLO}_r)$。</li>\n<li>调度器对每个 $p$ 计算计价 $\\text{Cost}_p \\propto h_p w_p N_{\\text{step}}$，按分辨率阈值与 SLO 等级投递到 fast 队列或 slow 队列。</li>\n<li>fast 队列以小编制、短 kernel 抢占式发射；slow 队列攒够大编制后整批发射，追求 Tensor Core 占用率。</li>\n<li>通道内独立去噪，结果写回 $r$ 的缓冲区；请求完成条件为 $\\forall p\\in P_r$ 均已写回。</li>\n</ul>\n<p>请求级 SLO 的判定因此变成 patch 级最大值：</p>\n<div class=\"formula\">$$\\text{SLO}_{\\text{req}} = \\max_{p\\in\\text{patches}} \\left(T_{\\text{queue},p} + T_{\\text{compute},p}\\right)$$</div>\n<p>这个式子暴露了算法的收益与风险：收益是快通道的 $T_{\\text{queue}}$ 不再被大请求拉长；风险是请求完成时间由最慢的那个 patch 决定，慢通道一旦排队过长，整个请求的 SLO 就被单个 patch 拖垮。工程上必须把这条 max 当作调度器的约束，而不是事后统计。</p>\n\n<h3 id=\"alg-mixed-res-serve-sec-4\">四 · 适用边界：它治什么，不治什么</h3>\n<p>适用场景有明确画像：高低分辨率混合负载、小请求 SLO 容易被长尾拖垮、GPU 上同时存在“轻请求等重请求”的现象。此时 patch 级分流让快通道的小 batch 与慢通道的大 batch 各自获得规整的 kernel 形状，Tensor Core 利用率高于混 batch，大小请求共享 GPU 而不互相阻塞。分辨率分级本身还带来一个副作用收益：同一通道内 patch 形状一致，GEMM 与注意力的 tile 划分更整齐，减少了形状抖动带来的发射开销。</p>\n<p>不适用或需谨慎的边界同样清楚。第一，**同质负载**：如果所有请求分辨率接近，切 patch 只增加拼接与队列开销，收益趋零。第二，**极低延迟单请求**：patch 切分与拼接的固定开销、重叠 halo 的额外算力，会直接吃掉小请求的延迟预算。第三，**规模上限受切分与拼接开销约束**：重叠 patch 增加显存与算力，patch 数越多，请求级缓冲区与融合后处理越重。第四，它不解决量化精度、不解决采样步数、不解决 VAE 解码瓶颈——这些分别属于 NVFP4 混合精度、少步采样、VAE 分块并行解码等条目，本算法只在采样阶段内部按 patch 分流。</p>\n<p>与相邻方案的边界也要划清：按请求整体调度的服务方案在请求级做批合并与优先级，遇到混合分辨率时仍受“最慢成员”支配；扩散流水线分阶段服务按 stage 拆分 DiT/VAE/后处理，解决的是阶段间资源错配，而本算法在采样阶段内部按 patch 分流，两者正交，可以叠加但不能互相替代。</p>\n\n<h3 id=\"alg-mixed-res-serve-sec-5\">五 · 失败模式：三个必须提前设计的坑</h3>\n<p>第一个坑是**边界伪影**。patch 切分与拼接在接缝处引入不连续，若重叠 halo 不足或融合后处理不当，拼接处出现接缝与色彩断层。这不是调度问题而是数值与后处理问题，但它由调度决策直接触发：patch 越小、通道间 kernel 差异越大，伪影越明显。工程代价是重叠区域带来的额外显存与算力，必须在切分策略里预留。</p>\n<p>第二个坑是**尾延迟被最慢 patch 支配**。慢通道大 batch 排队时，单个 patch 的 $T_{\\text{queue},p}$ 可以远超快通道成员的完成时间，整个请求的 SLO 由这个 max 决定。事故复盘里最常见的情形是：请求的多数 patch 早已写回缓冲区，最后一个 patch 卡在慢通道等大 batch 攒批。调度器需要对每个请求维护“剩余 patch 的最坏排队估计”，在接近 SLO 时把尾 patch 提升到快通道或拆小编制。</p>\n<p>第三个坑是**通道负载失衡导致资源匹配失效**。快/慢通道的 batch 编制若固定不变，负载配方偏移时会出现一条通道饿死、另一条通道堵死，GPU 资源匹配失效，吞吐与 SLO 同时受损。这要求通道编制是动态的：按队列深度与 SLO 余量调整快通道的抢占额度与慢通道的攒批阈值，而不是静态切分。</p>\n<table class=\"mini\"><thead><tr><th>失败模式</th><th>触发条件</th><th>系统代价</th><th>工程对策</th></tr></thead><tbody><tr><td>拼接伪影</td><td>halo 不足、融合后处理缺失</td><td>显存与算力上升，画质返工</td><td>重叠 patch + 融合后处理</td></tr><tr><td>尾延迟失控</td><td>慢通道攒批过久</td><td>请求 p99 被单 patch 拖垮</td><td>尾 patch 提升快通道</td></tr><tr><td>通道失衡</td><td>静态 batch 编制</td><td>吞吐与 SLO 同时下降</td><td>按队列深度动态调编制</td></tr></tbody></table>\n<p>把这三个坑放在一起看，会发现它们共同指向一个工程判断：patch 级调度的复杂度不在分流本身，而在**请求级缓冲区的生命周期管理与通道编制的动态性**。事故里的雪崩不是因为算法错，而是因为调度器把 patch 当成了独立任务、忘了请求级 max 这条约束。真正可用的实现，是在 patch 队列之上再压一层请求级 SLO 看门狗，让最慢 patch 始终处于被观测与被提升的状态。</p>\n\n\n<h3 id=\"alg-mixed-res-serve-sec-6\">六 · 什么时候不该切 patch：一条被长尾拖垮的产线事故</h3>\n<p>先看一个不涉及任何虚构数字的失败链条。某条线上服务同时承接两类请求：一类是低分辨率草图快速出图，用户在前端等着看构图；另一类是高分辨率成品图，允许较长等待。服务端沿用按请求整体调度的批处理逻辑，把同一时刻到达的请求塞进一个 batch。高分辨率请求的 DiT 计算量随像素平方增长，$$\\text{Cost}_{\\text{patch}} \\propto h\\cdot w\\cdot N_{\\text{step}}$$ 意味着它的单步开销远大于低分辨率请求，而扩散采样要跑满整个去噪步数。于是这个混合 batch 的每一步都被最大的那张图钉住，小请求既拿不到自己的低延迟 kernel，也等不到 batch 结束——它们被\"搭便车\"式地绑在长请求上。请求级 SLO 的实际形态是 $$\\text{SLO}_{\\text{req}} = \\max_{p\\in\\text{patches}} \\left(T_{\\text{queue},p} + T_{\\text{compute},p}\\right)$$，在整体调度下这个 max 直接退化为\"最慢那张图的时间\"，小请求的 SLO 全线击穿，而 GPU 因为 batch 内 kernel 形状参差、Tensor Core 利用率被拉低，整体吞吐同步下滑。这不是容量不够，是调度粒度错了：请求是不可分割的调度单位，而请求内部的成本分布极不均匀。</p>\n<p>混合分辨率补丁调度要解决的正是这个粒度问题：把请求按目标分辨率切成 patch 集合、标注 SLO 等级，再由 patch 调度器按分辨率与 SLO 分流到快通道（小 batch、低延迟 kernel）与慢通道（大 batch、高吞吐 kernel），各通道独立采样去噪，结果写回请求级缓冲区，全部 patch 到齐后拼接、VAE 解码返回。它换来的是大小请求共享同一块 GPU 而不互相阻塞，以及分辨率分级后 kernel 形状更规整、Tensor Core 利用率高于混 batch。但它明确不解决另一类问题：如果负载本身就是单一分辨率、SLO 等级一致，切 patch 只是凭空引入切分与拼接开销，收益为零；如果瓶颈在 VAE 解码或后处理而非 DiT 采样，patch 级分流对端到端延迟几乎没有贡献；如果请求对全局一致性极度敏感（例如需要整图风格统一、跨区域语义连贯），patch 独立去噪本身就是风险源，这不是调度能修的。</p>\n<p>边界之外是硬代价，必须写进容量模型。第一是边界伪影：patch 切分与拼接在接缝处产生色彩断层与结构错位，抑制手段是重叠 halo 加融合后处理，代价是显存与算力双重上升——重叠区域被重复计算，缓冲区要容纳 halo 副本，切得越细、重叠越大，这部分开销占比越高，构成该方案的规模上限。第二是尾延迟结构没变，只是换了支配者：请求级 SLO 仍是 max 形式，慢通道大 batch 排队时，单个 patch 的排队时间就能拖垮整个请求，patch 级队列必须做跨通道的负载均衡，否则快通道空转、慢通道积压，GPU 资源匹配失效，吞吐与 SLO 同时受损。第三是逻辑复杂度：patch 队列、写回缓冲、拼接与融合后处理构成一条新的状态机，任何一处失衡都会以接缝或超时的形式暴露在用户侧。判断是否采用它，只需问三个问题：负载是否真是高低分辨率混合、小请求 SLO 是否已被长尾击穿、拼接开销能否被吞吐收益覆盖——三者缺一，就该退回请求级调度或先解决 VAE 瓶颈。</p>\n<h3 id=\"alg-mixed-res-serve-sec-7\">七 · 请求切分：patch 集合与 SLO 标注的生成</h3>\n<p>请求进入调度器的第一个动作不是排队，而是切分。调度器读取请求的目标分辨率 $H\\times W$ 与请求级 SLO 等级，把整幅图切成 $P$ 个 patch，每个 patch 携带三元组：空间坐标、patch 分辨率、SLO 等级。这一步的输入是请求元数据（分辨率、SLO、步数 $N_{\\text{step}}$），输出是 patch 描述符数组，代价是纯 CPU 侧的几何计算加上描述符内存——描述符本身很小，但重叠 halo 的引入会让后续显存占用按 $(h+2\\delta)(w+2\\delta)$ 而非 $h\\cdot w$ 计。</p>\n<p>切分策略直接决定后面所有步骤的形状规整度。若按固定网格切，patch 分辨率一致，快慢通道的 kernel 形状天然规整；若按分辨率自适应切，高分辨率请求被切成更多小块以塞进快通道，代价是 patch 数量上升、拼接逻辑变复杂。这里的关键判断是：切分粒度要与通道的 batch 形状对齐，否则慢通道拿到一堆尺寸参差的 patch，Tensor Core 利用率回落到混 batch 的水平，patch 级调度就失去了意义。切分阶段还要为每个 patch 标注 SLO 等级——注意标注的是 patch 继承的请求级 SLO，而非 patch 自身独立的 SLO，因为最终 $\\text{SLO}_{\\text{req}}=\\max_{p}(T_{\\text{queue},p}+T_{\\text{compute},p})$ 由最慢 patch 决定。</p>\n<p>具体例子：一个高分辨率请求与若干低分辨率请求同时到达，高分辨率请求被切成 16 个 patch 并标注高 SLO 等级，低分辨率请求各自切成 1–4 个 patch 标注低等级。切分完成后，请求级缓冲区按 patch 数量预分配，重叠 halo 使该缓冲区的显存需求高于按原图尺寸估算的值。</p>\n\n<h3 id=\"alg-mixed-res-serve-sec-8\">八 · 分通道入队：分辨率与 SLO 的双键路由</h3>\n<p>patch 调度器拿到描述符数组后执行路由：以（patch 分辨率，SLO 等级）为双键，把 patch 压入快通道队列或慢通道队列。输入是 patch 描述符，输出是两条队列的排队序列，代价体现在排队时延 $T_{\\text{queue},p}$ 上——这是 $\\text{SLO}_{\\text{req}}$ 公式里的第一项，也是 patch 级调度最容易失控的地方。</p>\n<p>路由规则不是简单的“小 patch 进快通道”，而是要让快通道保持小 batch、低延迟的 kernel 形状，慢通道保持大 batch、高吞吐的 kernel 形状。若一个高 SLO 的小 patch 被误判进慢通道，它会在慢通道的大 batch 里排队，$T_{\\text{queue},p}$ 被拉长，直接拖垮整个请求的 SLO；反之，低 SLO 的大 patch 挤进快通道会撑爆快通道的 batch 上限，让快通道失去低延迟特性。双键路由的本质是把“形状”和“紧迫度”解耦：形状决定进哪条通道，紧迫度决定在通道内的优先级。</p>\n<p>代价的量化方式是队列深度与通道负载比。快通道队列深度受小 batch 上限约束，深度过大会让低延迟承诺失效；慢通道队列深度受大 batch 填充率约束，填充不足则吞吐下降。两条通道的负载比失衡时，GPU 资源匹配失效，吞吐与 SLO 同时受损——这是本算法明确的失败模式之一。工程上需要在路由层做准入控制：当慢通道排队时延逼近某请求的 SLO 余量时，把该请求的 patch 拆得更细以分流到快通道，或直接拒绝该请求而不是让它拖垮整批。</p>\n\n<h3 id=\"alg-mixed-res-serve-sec-9\">九 · 通道内采样去噪：两种 kernel 形状的独立执行</h3>\n<p>两条通道各自独立采样去噪，这是 patch 级调度与请求级调度的分水岭。快通道用小 batch、低延迟 kernel，单次前向的 batch 维度小，kernel 启动开销占比高但单步延迟低；慢通道用大 batch、高吞吐 kernel，batch 维度大，单步延迟高但单位 patch 的摊销成本低。输入是通道内的 patch 批次与步数 $N_{\\text{step}}$，输出是去噪后的 patch 潜变量，代价是每步的 $\\text{Cost}_{\\text{patch}}\\propto h\\cdot w\\cdot N_{\\text{step}}$ 加上 kernel 启动与同步开销。</p>\n<div class=\"formula\">$$\\text{Cost}_{\\text{patch}} \\propto h\\cdot w\\cdot N_{\\text{step}},\\quad \\text{SLO}_{\\text{req}} = \\max_{p\\in\\text{patches}} \\left(T_{\\text{queue},p} + T_{\\text{compute},p}\\right)$$</div>\n<p>公式说明两件事：单 patch 的计算代价随其面积与步数线性增长，而请求级 SLO 由最慢 patch 的排队加计算时间支配。这意味着慢通道的大 batch 虽然摊销了单位成本，但一旦某个 patch 在慢通道里排到队尾，它的 $T_{\\text{queue},p}$ 会单独放大整个请求的 $\\text{SLO}_{\\text{req}}$。工程判断是：慢通道的 batch 填充要优先服务那些“已经是请求内最慢 patch”的成员，而不是盲目追求 batch 大小。</p>\n<p>具体例子：一个被切成 16 个 patch 的高分辨率请求，其中 12 个 patch 进了慢通道、4 个进了快通道。快通道的 4 个 patch 早早完成，但请求要等慢通道里最后一个 patch 出队才能拼接——此时请求级尾延迟完全由慢通道的排队决定，快通道的低延迟没有转化为请求级收益。这正是需要重叠 halo 与融合后处理之外，还要在通道间做负载均衡的原因。</p>\n\n<h3 id=\"alg-mixed-res-serve-sec-10\">十 · 结果写回与请求级缓冲：拼接前的数据落位</h3>\n<p>每个 patch 去噪完成后写回请求级缓冲区。输入是 patch 潜变量与其空间坐标，输出是缓冲区中按坐标落位的张量片段，代价是写带宽与缓冲区显存。这一步看似平凡，实则是 patch 级调度显存代价的主要来源：重叠 halo 意味着相邻 patch 在边界处有重复像素，写回时这些重复区域要么被覆盖、要么被保留待融合，前者省显存但丢信息，后者保信息但缓冲区尺寸按 $(h+2\\delta)(w+2\\delta)$ 累加。</p>\n<p>写回的同步语义也需要设计。若每个 patch 完成即写回，缓冲区成为多通道并发写的共享资源，需要按坐标分区避免写冲突；若等通道内整批完成再写回，缓冲区写入是批量的，带宽利用率高但请求级尾延迟被批内最慢 patch 拉长。工程上通常选择按 patch 完成即写回、按坐标分区，把同步开销压到最小，代价是缓冲区管理逻辑变复杂——这是“patch 级队列与拼接逻辑复杂导致调度失误”这一失败模式的直接来源。</p>\n<p>具体例子：重叠 halo 取若干像素时，16 个 patch 的缓冲区总尺寸明显大于原图，若同时有多个高分辨率请求在飞，请求级缓冲区的显存占用会成为并发度的实际上限。此时调度器需要在准入阶段就按缓冲区显存做并发控制，而不是等到写回时才因显存不足触发换出。</p>\n\n<h3 id=\"alg-mixed-res-serve-sec-11\">十一 · 拼接、融合与 VAE 解码：尾延迟的最终结算</h3>\n<p>全部 patch 完成后，调度器触发拼接：按空间坐标把 patch 潜变量拼成完整潜图，对重叠 halo 区域做融合后处理以抑制接缝与色彩断层，然后送入 VAE 解码并返回图像。输入是请求级缓冲区中的全部 patch 结果，输出是最终图像，代价是拼接的访存开销、融合后处理的计算开销以及 VAE 解码的显存与算力——后者在分块并行解码的场景下另有专门机制，此处只需知道它是请求级尾延迟的最后一个组成部分。</p>\n<p>这一步的工程判断集中在融合质量与尾延迟的权衡。重叠 halo 不足或融合后处理不当，拼接处出现接缝与色彩断层，这是本算法列明的首要失败模式；halo 加宽能抑制伪影，但缓冲区显存与融合算力同步上升，且宽 halo 让 patch 的有效计算面积变大，$\\text{Cost}_{\\text{patch}}$ 随 $h\\cdot w$ 上升。融合后处理的实现方式也影响尾延迟：逐像素加权融合是访存密集型，在拼接阶段引入的时延与 patch 数量成正比；若把融合下推到写回阶段做增量融合，尾延迟被摊薄，但写回逻辑更复杂。</p>\n<p>最终 $\\text{SLO}_{\\text{req}}$ 在这一步结算：拼接与融合的时延加上 VAE 解码时延，叠加在已经发生的 $\\max_{p}(T_{\\text{queue},p}+T_{\\text{compute},p})$ 之上。若拼接阶段才发现某个 patch 结果缺失或坐标错位，整个请求需要重算，尾延迟直接爆掉——所以拼接前的完整性校验必须前置到写回阶段，而不是留到拼接时才发现。</p>\n\n<h3 id=\"alg-mixed-res-serve-sec-12\">十二 · 步骤间的耦合与调度失误的传播路径</h3>\n<p>把五个步骤串起来看，patch 级调度的代价不是各步骤代价的简单相加，而是沿数据流传播的。切分阶段的粒度选择决定了通道内 kernel 形状的规整度；路由阶段的负载比决定了 $T_{\\text{queue},p}$ 的分布；采样阶段的 batch 填充策略决定了哪个 patch 成为请求内最慢者；写回阶段的缓冲区显存决定了并发度上限；拼接阶段的 halo 宽度决定了伪影抑制与算力开销的平衡。任一环节的失误都会沿这条链放大：切分过细导致 patch 数量膨胀，路由层队列深度上升，慢通道排队拉长，最终由 $\\max_{p}$ 结算成请求级 SLO 违约。</p>\n<p>工程上的防御手段是让每一步都输出可观测的量：切分阶段记录 patch 数量与 halo 开销比，路由阶段记录双通道队列深度与负载比，采样阶段记录每 patch 的排队与计算时延，写回阶段记录缓冲区占用，拼接阶段记录融合时延。这些量共同构成 patch 级调度的容量规划输入——规模上限受 patch 切分与拼接开销约束，重叠 patch 增加显存与算力，请求级尾延迟受最慢 patch 支配，具体规模数值需按上述观测量在部署中实测确定，而非套用固定阈值。</p>\n<p>最后落在一个具体机制上：慢通道的 batch 填充应以“请求内最慢 patch 优先”为准则，即路由层为每个请求维护一个未完成 patch 集合，当慢通道有空位时优先拉入那些属于即将到期请求的 patch，而不是按到达顺序填充。这个准则把 $\\max_{p}$ 的结算从被动等待变成主动干预，是 patch 级调度在混合负载下同时改善吞吐与 SLO 的关键工程判断。</p>\n\n<h3 id=\"alg-mixed-res-serve-sec-13\">十三 · 快慢通道的边界：patch 分流在什么条件下反噬</h3>\n<p>patch 级分流的收益并非无条件成立，它依赖一个隐含前提：快通道的 patch 集合能在慢通道排队期间持续喂饱 GPU。设快通道批大小为 <span class=\"inline-math\">$b_f$</span>、慢通道为 <span class=\"inline-math\">$b_s$</span>，单 patch 计算代价为 <span class=\"inline-math\">$c(h,w)$</span>，则快通道单步时延约正比于 <span class=\"inline-math\">$b_f\\cdot c$</span>，慢通道吞吐约正比于 <span class=\"inline-math\">$b_s/c$</span>。当低分辨率 patch 到达率不足以填满 <span class=\"inline-math\">$b_f$</span> 时，快通道 kernel 进入欠占用状态，Tensor Core 空转，此时“小 batch 低延迟”退化为“小 batch 低利用率”，分流反而比混 batch 更贵。反过来，若高分辨率 patch 大量涌入而慢通道 batch 已满，patch 在慢通道队列中排队，请求级 SLO 由最慢 patch 支配：</p>\n<div class=\"formula\">$$\\text{SLO}_{\\text{req}} = \\max_{p\\in\\text{patches}} \\left(T_{\\text{queue},p} + T_{\\text{compute},p}\\right)$$</div>\n<p>这意味着一个请求的完成时间不是其 patch 的平均值，而是最大值。慢通道一次大 batch 采样跨越多个去噪 step，排队延迟被 step 数放大，单个高分辨率 patch 即可拖垮整个请求。失效条件是明确的：当请求内 patch 分辨率方差大、且慢通道负载已接近饱和时，patch 分流的尾延迟惩罚超过其吞吐收益。</p>\n<p>第二类失效来自切分本身。重叠 halo 是抑制接缝的必要代价，设 halo 宽度为 <span class=\"inline-math\">$r$</span>、patch 边长为 <span class=\"inline-math\">$s$</span>，则有效计算量放大约为 <span class=\"inline-math\">$\\left(\\frac{s+2r}{s}\\right)^2$</span>，显存占用同比例上升；若 <span class=\"inline-math\">$r$</span> 小于 DiT 感受野对应的最小重叠，拼接处出现色彩断层与结构断裂，融合后处理只能掩盖不能消除。第三类是调度器自身的复杂度代价：快慢通道共享同一 GPU 资源池，负载失衡时通道间无法互相借力，patch 级队列的优先级反转与拼接缓冲区的生命周期管理都会引入额外的主机侧开销与显存驻留。工程判断是：patch 分流适用于分辨率分层清晰、低分辨率请求占比足以维持快通道占用的混合负载；当请求分辨率分布连续、或慢通道已长期饱和时，应退回请求级调度并以分辨率分桶替代 patch 切分。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>直接代价</th><th>观测信号</th></tr></thead><tbody><tr><td>快通道欠占用</td><td>Tensor Core 利用率下降，吞吐低于混 batch</td><td>快通道 batch 填充率持续偏低</td></tr><tr><td>慢通道排队饱和</td><td>请求级尾延迟被最慢 patch 支配</td><td>请求完成时间方差随分辨率方差增大</td></tr><tr><td>halo 不足</td><td>接缝与色彩断层，需返工重采样</td><td>拼接边界梯度异常</td></tr></tbody></table>\n<h3 id=\"alg-mixed-res-serve-sec-14\">十四 · 逐项拆解 Cost_patch 与 SLO_req 两个核心式</h3>\n<p>本部分只做一件事：把混合分辨率补丁调度里那两个决定调度决策的式子拆到每一项都能对应到 GPU 上的具体资源，再给出可直接落地的伪代码。前两式分别是 <span class=\"formula\">$$\\text{Cost}_{\\text{patch}} \\propto h\\cdot w\\cdot N_{\\text{step}}$$</span> 与 <span class=\"formula\">$$\\text{SLO}_{\\text{req}} = \\max_{p\\in\\text{patches}} \\left(T_{\\text{queue},p} + T_{\\text{compute},p}\\right)$$</span>。第一式是<em>容量式</em>，回答“这个 patch 要吃掉多少算力”；第二式是<em>约束式</em>，回答“这个请求能不能在承诺时间内返回”。两者共同构成调度器的目标函数骨架：在满足第二式的前提下，让第一式的总和在 GPU 上被压到最小。</p>\n<p>先看 Cost_patch。$h\\cdot w$ 是 patch 的像素面积，它进入 DiT 的方式不是线性的，而是经由 token 数间接放大：patch 被 VAE 编码后按 patch size 下采样，token 数 $N_{\\text{tok}} = \\frac{h w}{s^{2}}$（$s$ 为 VAE 空间下采样倍率），而 DiT 每个去噪步的注意力与 GEMM 代价对 $N_{\\text{tok}}$ 近似二次与线性混合——注意力是 $O(N_{\\text{tok}}^{2} d)$，GEMM 是 $O(N_{\\text{tok}} d^{2})$。所以在 $N_{\\text{tok}}$ 尚未大到注意力主导之前，Cost_patch 对面积近似线性；一旦跨过注意力拐点，面积翻倍带来的代价超过翻倍。$N_{\\text{step}}$ 是去噪步数，它与面积相乘意味着：<strong>步数是可乘的杠杆</strong>，把高分辨率 patch 的步数压下来（配合少步采样器）比缩小 patch 面积更划算，因为面积缩小会破坏 patch 形状规整性、增加拼接开销，而步数缩减不改变 kernel 形状。</p>\n<p>再看 SLO_req。$\\max_{p}$ 而非 $\\sum_{p}$ 是关键一步推导：请求的完成时刻等于最后一个 patch 完成的时刻，而不是所有 patch 耗时之和——因为 patch 在通道内是并行推进的。于是请求级尾延迟被最慢 patch 支配，这正是失败模式“单个 patch 拖垮整个请求”的数学来源。$T_{\\text{queue},p}$ 是 patch 在通道队列里的排队时间，由通道的 batch 组装策略与当前负载决定；$T_{\\text{compute},p}$ 是实际 kernel 执行时间，由 patch 形状、batch 大小与 kernel 选择决定。把两者相加再取 max，就把“调度”与“计算”两类延迟统一进了一个可比较的标量。</p>\n\n<h3 id=\"alg-mixed-res-serve-sec-15\">十五 · 推导的关键一步：从请求级平方增长到 patch 级线性可加</h3>\n<p>原始问题是请求级代价随像素平方增长：$C_{\\text{req}} \\propto H\\cdot W$ 在 token 层面被放大为近似平方，导致一个大请求在混 batch 中把整个 batch 的 kernel 时间拉长，小请求被迫陪跑。推导的关键一步是<strong>把请求级代价函数改写为 patch 级代价的可加组合，并把 max 从请求级下放到 patch 级</strong>。设请求被切为 $P$ 个 patch，每个 patch 面积 $h_i w_i$，则</p>\n<div class=\"formula\">$$C_{\\text{req}} = \\sum_{i=1}^{P} \\text{Cost}_{\\text{patch},i} + C_{\\text{stitch}},\\quad C_{\\text{stitch}} = \\alpha \\sum_{i} \\left(h_i w_i - (h_i-\\delta)(w_i-\\delta)\\right)$$</div>\n<p>其中 $\\delta$ 是重叠 halo 宽度，$C_{\\text{stitch}}$ 是重叠区带来的额外编码/解码与融合代价，$\\alpha$ 是单位重叠像素的融合开销系数。这一步的意义在于：原本不可分的请求级平方项，被拆成了 $P$ 个形状可控的小块之和，加上一个与 halo 周长成正比的拼接项。拼接项是纯开销，不产生有效像素，因此调度器必须让 $\\delta$ 尽量小、patch 尽量大——但 patch 越大，慢通道排队越久，SLO_req 的 max 项越容易被拖高。这就是本算法的核心张力：<strong>patch 尺寸同时进入 Cost_patch 的可加项与 SLO_req 的 max 项，前者希望小、后者希望大</strong>。</p>\n<p>把两式联立，调度问题可写成：给定请求集合与各自 SLO 等级，选择切分方案 $\\{(h_i,w_i,\\delta)\\}$ 与通道分配，最小化 $\\sum C_{\\text{patch}}$ 满足每个请求 $\\max_p(T_{\\text{queue},p}+T_{\\text{compute},p}) \\le \\text{SLO}_{\\text{req}}$。这是一个带 max 约束的组合优化，工程上不求解精确最优，而是用分级规则近似：低分辨率 patch 面积小、$N_{\\text{step}}$ 少，Cost_patch 低，进快通道；高分辨率 patch 面积大，进慢通道用大 batch 摊薄 $T_{\\text{queue},p}$ 的固定开销。分级规则把优化问题降维成查表，代价是失去全局最优性，收益是调度延迟可忽略。</p>\n\n<h3 id=\"alg-mixed-res-serve-sec-16\">十六 · 伪代码：patch 切分、通道分配与写回</h3>\n<p>下面给出可直接实现的调度骨架。切分阶段按目标分辨率与 SLO 等级决定 patch 网格与 halo；分配阶段按面积阈值与通道水位决定入队；写回阶段用请求级缓冲区做重叠区加权融合。伪代码用文字描述结构，避免代码围栏。</p>\n<ul>\n<li>输入：请求 $r$，目标分辨率 $(H,W)$，SLO 等级 $g$，VAE 下采样倍率 $s$，halo 宽度 $\\delta$。</li>\n<li>步骤 1（切分）：令 patch 边长 $b = \\text{grid}(H,W,g)$，网格 $n_h=\\lceil H/b\\rceil$，$n_w=\\lceil W/b\\rceil$；每个 patch 取 $[y b-\\delta, (y+1)b+\\delta]\\times[x b-\\delta,(x+1)b+\\delta]$ 的扩展区域，记录有效区与 halo 区。</li>\n<li>步骤 2（代价估计）：对每个 patch 计算 $\\hat{C}_i = h_i w_i N_{\\text{step}}(g)$，并按通道历史吞吐估计 $\\hat{T}_{\\text{compute},i}$ 与当前队列长度估计 $\\hat{T}_{\\text{queue},i}$。</li>\n<li>步骤 3（通道选择）：若 $\\hat{C}_i \\le \\theta_{\\text{fast}}$ 且快通道水位低于上限，入快通道；否则入慢通道。$\\theta_{\\text{fast}}$ 由快通道 kernel 的最优 batch 形状反推，不是固定像素阈值。</li>\n<li>步骤 4（采样去噪）：各通道独立执行 $N_{\\text{step}}$ 步去噪，快通道用小 batch、低延迟 kernel 配置，慢通道用大 batch、高吞吐 kernel 配置；通道间不共享 batch，避免形状混叠。</li>\n<li>步骤 5（写回）：patch 结果写入请求级缓冲区对应有效区，halo 区按距离加权叠加到相邻 patch 的有效区边缘。</li>\n<li>步骤 6（完成判定）：当请求所有 patch 的有效区均被写满，触发拼接与 VAE 解码；若某 patch 超时，按降级策略（缩步数或换通道）重排。</li>\n</ul>\n<p>伪代码里最容易被忽略的是步骤 3 的 $\\theta_{\\text{fast}}$ 来源。它不是拍脑袋的像素数，而是从快通道 kernel 的 batch 形状上限反推：快通道为了低延迟，batch 被限制在一个小范围内，超过这个范围的 patch 塞进去会让 kernel 退化到低效形状，反而拉高 $T_{\\text{compute},p}$。因此阈值应随通道当前 batch 组装情况动态调整，而不是静态配置。</p>\n\n<h3 id=\"alg-mixed-res-serve-sec-17\">十七 · 代价落到资源：延迟、吞吐、显存、带宽</h3>\n<p>把公式映射到 Blackwell 资源账本上，才能判断调度是否真的省。延迟侧，快通道的 $T_{\\text{compute},p}$ 由小 batch kernel 的启动开销与单步 GEMM 主导，patch 越小启动开销占比越高，因此快通道存在一个“最小有效 patch 面积”，低于它则 kernel launch 与 TMEM 搬运开销吃掉收益。吞吐侧，慢通道用大 batch 把权重读取摊薄，$T_{\\text{queue},p}$ 上升但单位 patch 的算力成本下降；两通道的吞吐比取决于大 batch 的 GEMM 效率与小 batch 的延迟容忍度，工程上以通道各自的 patch 吞吐（patch/s）为观测指标做水位控制。</p>\n<p>显存侧，重叠 halo 直接放大激活与中间缓冲：每个 patch 的 token 数按 $(b+2\\delta)^2/s^2$ 计，而有效 token 只有 $b^2/s^2$，重叠比例 $\\rho = \\left(1+\\frac{2\\delta}{b}\\right)^2-1$。$\\rho$ 是显存的纯增量，且随 $\\delta/b$ 平方增长。请求级缓冲区还要为每个请求保留全部 patch 的输出，峰值显存约为单 patch 输出的 $P$ 倍再乘融合临时区。带宽侧，patch 写回与 halo 融合是纯内存搬运，不产生算力，却占用 HBM 带宽；当通道并行度高时，写回带宽会与采样阶段的权重读取争抢，成为隐性瓶颈。功耗侧，快通道频繁的小 kernel 启动带来更高的单位算力能耗，慢通道大 batch 的单位算力能耗更低，因此混合负载的整体能效取决于快慢通道的 patch 比例。</p>\n<table class=\"mini\"><thead><tr><th>资源维度</th><th>快通道</th><th>慢通道</th><th>调度含义</th></tr></thead><tbody><tr><td>延迟</td><td>小 batch，启动开销占比高</td><td>大 batch，排队时间长</td><td>快通道设最小 patch 面积下限</td></tr><tr><td>吞吐</td><td>单位 patch 算力成本高</td><td>权重摊薄，算力成本低</td><td>按通道 patch/s 做水位控制</td></tr><tr><td>显存</td><td>halo 比例随 δ/b 平方增长</td><td>请求级缓冲区峰值高</td><td>δ 与 b 联合约束，限制 P 上限</td></tr><tr><td>带宽</td><td>写回与融合搬运</td><td>权重读取为主</td><td>写回与采样错峰</td></tr></tbody></table>\n\n<h3 id=\"alg-mixed-res-serve-sec-18\">十八 · 具体例子：一个混合负载请求的调度走位</h3>\n<p>设一个请求目标分辨率较高，被切为 $4\\times4$ 共 16 个 patch，SLO 等级为紧。按面积阈值，其中 12 个位于图像主体、面积较大的 patch 进慢通道，4 个位于边缘、面积较小的 patch 进快通道。慢通道当前队列已有若干大 patch 在排队，$T_{\\text{queue},p}$ 估计值偏高；快通道水位低，$T_{\\text{queue},p}$ 接近零。此时 SLO_req 的 max 项落在慢通道的某个 patch 上，请求尾延迟由它支配。调度器的动作不是把边缘 patch 也塞进慢通道凑 batch，而是反过来：把慢通道中与本次请求同分辨率的 patch 合并成更大 batch 以摊薄单 patch 的 $T_{\\text{compute},p}$，同时把快通道的边缘 patch 提前发射，让它们的写回与慢通道采样重叠。最终请求完成时刻取决于慢通道最后一个 patch，但快通道的提前完成让拼接阶段的 halo 融合可以流水进行，而不是等全部 patch 到齐再串行融合。</p>\n<p>这个例子暴露了公式的一个工程细节：$\\max_p$ 里的 $T_{\\text{queue},p}$ 是动态量，调度器在请求进入时估计一次、在 patch 入队后还要重估。若慢通道排队在请求生命周期内恶化，原本满足 SLO 的估计会失效，此时需要触发降级——把最慢 patch 的 $N_{\\text{step}}$ 缩减（若采样器支持）或把该 patch 拆小转入快通道，用面积换队列时间。降级会引入 patch 形状不一致，增加拼接复杂度，因此只在估计超时裕度不足时启用。</p>\n\n<h3 id=\"alg-mixed-res-serve-sec-19\">十九 · 伪代码落到可实现：三个必须写死的工程约束</h3>\n<p>第一，patch 网格与 halo 必须在请求进入时一次性确定并冻结，不能在采样中途改切分，否则请求级缓冲区无法复用、写回地址失效。第二，通道分配必须带水位上限与回退路径：快通道满时不得无限排队，应回退到慢通道或触发降级，否则快通道退化为第二个慢通道，分级失去意义。第三，拼接与融合必须是幂等且可并行的：每个 patch 只写自己的有效区，halo 区只读不写，融合按预计算的权重表叠加，这样任一 patch 迟到不会阻塞其他 patch 的写回，请求级尾延迟只由真正最慢的 patch 决定，而不是由拼接逻辑的串行性决定。</p>\n<p>把这三条约束代回公式，可以看到调度器的实际决策变量只有两个：patch 边长 $b$（决定 Cost_patch 的可加项与 halo 比例）与通道水位阈值（决定 $T_{\\text{queue},p}$ 的分布）。$N_{\\text{step}}$ 由采样器与 SLO 等级给定，不是调度自由度；$\\delta$ 由画质约束给定，也不是自由度。因此调度的本质是在 $b$ 与水位之间做二维搜索，而 SLO_req 的 max 结构决定了搜索目标不是平均延迟最小，而是<strong>最慢 patch 的延迟裕度最大</strong>——这正是分级调度与按请求整体调度的根本分野：后者优化平均，前者优化尾部。</p>\n\n<h3 id=\"alg-mixed-res-serve-sec-20\">二十 · 补写：patch 代价模型与尾延迟边界</h3>\n<p>把 <span class=\"formula-inline\">$$\\text{Cost}_{\\text{patch}} \\propto h\\cdot w\\cdot N_{\\text{step}}$$</span> 逐项拆开看：$h\\cdot w$ 是单个 patch 的像素面积，决定该 patch 在一次 DiT 前向中的 token 数与注意力矩阵规模；$N_{\\text{step}}$ 是该 patch 实际执行的采样步数。三项相乘而非相加，意味着任何一项失控都会线性放大该 patch 的占用时间——这正是快/慢通道必须按分辨率而非按请求切分的理由。推导的关键一步是把请求级 SLO 约束改写为 patch 级约束：请求完成时刻等于最慢 patch 的完成时刻，于是 <span class=\"formula-inline\">$$\\text{SLO}_{\\text{req}} = \\max_{p\\in\\text{patches}} \\left(T_{\\text{queue},p} + T_{\\text{compute},p}\\right)$$</span> 成立，$T_{\\text{queue},p}$ 由所属通道的批大小与排队深度决定，$T_{\\text{compute},p}$ 由 $h\\cdot w\\cdot N_{\\text{step}}$ 与 kernel 形状共同决定。这个 max 结构直接给出边界条件：只要有一个 patch 落入慢通道且排队过深，整个请求的 SLO 就被它单独支配，其余 patch 再快也无济于事。</p>\n<p>失效条件因此可以写成可判定的不等式。设请求被切为 $k$ 个 patch，其中高分辨率 patch 集合 $\\mathcal{H}$ 走慢通道，若 <span class=\"formula-inline\">$$\\max_{p\\in\\mathcal{H}} \\left(T_{\\text{queue},p} + T_{\\text{compute},p}\\right) &gt; \\text{SLO}_{\\text{req}}$$</span>，则该请求必然违约，无论快通道多空闲。工程上要防的是慢通道大 batch 的排队放大：批越大，单 patch 的 $T_{\\text{queue}}$ 越被前面已入队的 patch 拉长，而 $T_{\\text{compute}}$ 的收益来自 Tensor Core 利用率提升，两者方向相反。伪代码落到可实现层面，调度器每轮只需做三件事：按 $h\\cdot w$ 与标注的 SLO 等级把新 patch 压入快/慢队列；对慢队列做准入判断，若队首 patch 的预估 $T_{\\text{queue}}+T_{\\text{compute}}$ 已越过其请求 SLO 余量，则拒绝入队或降级为拆分更细的 patch；快队列维持小 batch 以压低 $T_{\\text{compute}}$ 的固定开销。判断所需的预估量可由上一轮同形状 patch 的实测耗时回填，不需要解析模型。</p>\n<p>系统代价集中在三处。其一是重叠 halo：为抑制拼接接缝与色彩断层，相邻 patch 需带重叠区并在融合后处理中加权，重叠比例直接抬高有效像素面积，使 $\\text{Cost}_{\\text{patch}}$ 中的 $h\\cdot w$ 项大于名义切分面积，同时增加显存驻留与后处理算力。其二是请求级缓冲区：各通道独立采样去噪后结果写回请求级缓冲区，缓冲区容量随 patch 数与分辨率线性增长，是显存占用的主要增量。其三是调度复杂度：快/慢通道负载失衡时，patch 级队列的资源匹配失效，吞吐与 SLO 同时受损，且这种失衡在混合负载下不易从单请求视角察觉。一张小表可概括边界：</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>后果</th><th>工程对策</th></tr></thead><tbody><tr><td>halo 不足或融合后处理不当</td><td>拼接处接缝、色彩断层</td><td>加大重叠区，融合权重按距离衰减</td></tr><tr><td>慢通道排队过深</td><td>单 patch 拖垮请求 SLO</td><td>准入判断 + 超限 patch 再切分</td></tr><tr><td>快/慢通道负载失衡</td><td>GPU 资源匹配失效，吞吐与 SLO 双降</td><td>按队列深度动态调整通道配额</td></tr></tbody></table>\n<p>适用规模的上限由切分与拼接开销与最慢 patch 的尾延迟共同约束，而非由 GPU 峰值算力约束；当重叠比例与 patch 数上升使后处理成为瓶颈时，patch 级分流的收益被抵消。因此该方案的工程判断应落在：混合负载中高分辨率请求占比越高、SLO 分层越明确，patch 级调度越值得；反之若请求分辨率单一，按请求整体调度即可，引入 patch 队列只会增加拼接逻辑与尾延迟风险。</p>\n<h3 id=\"alg-mixed-res-serve-sec-21\">二十一 · 请求形态：什么样的负载才配得上 patch 级分流</h3>\n<p>patch 级调度的收益不是无条件成立的，它由请求集合的<strong>分辨率离散度</strong>决定。设一个到达批次里有 $n$ 个请求，目标分辨率记为 $R_i=(H_i,W_i)$，则整个 batch 的 DiT 计算量被最大的那个请求支配：$\\max_i C_i \\propto \\max_i H_i W_i$。当所有请求分辨率接近时，这个 max 与均值差别很小，切 patch 只是把规整的大 kernel 拆成若干小 kernel，白白付出切分、halo 与拼接的代价。只有当分辨率分布呈明显双峰或多峰——例如一批 512×512 的草稿图与一批 2048×2048 的成品图同时到达——把大请求拆成 patch 集合、让小请求走快通道，才能把被大请求撑爆的 batch 重新压回各自的形状。因此负载配方的第一条判断是：混合分辨率且高分辨率请求占比不可忽略，才是这套调度的目标场景；单一分辨率或分辨率跨度小于一个 patch 档位的负载，应直接走请求级连续批处理。</p>\n<p>请求形态还包含 SLO 等级的可标注性。机制要求请求进入时“标注 SLO 等级”，这意味着服务侧必须能对每个请求给出一个可比较的时限标签（交互式预览、批量出图、离线补图）。若上游无法区分等级，所有 patch 只能进同一队列，快/慢通道退化为一个通道，patch 级队列失去分流依据。工程上这通常由 API 层的 priority 字段或租户配额映射而来，而不是调度器自行推断。</p>\n<ul>\n<li>适合：分辨率双峰分布、交互式与批量请求共存、小请求 SLO 明显紧于大请求。</li>\n<li>不适合：分辨率单一、请求全部离线且无时限、高分辨率请求占比极低（拆 patch 开销盖过收益）。</li>\n</ul>\n\n<h3 id=\"alg-mixed-res-serve-sec-22\">二十二 · 长度分布：patch 数量本身就是“序列长度”</h3>\n<p>在这套调度里，一个请求被切成的 patch 数 $N_{\\text{patch}}=\\lceil H/h_p\\rceil\\cdot\\lceil W/w_p\\rceil$ 扮演了类似序列长度的角色，而每个 patch 的去噪步数 $N_{\\text{step}}$ 决定其时间跨度。请求的总计算代价可写成 patch 代价之和：</p>\n<div class=\"formula\">$$\\text{Cost}_{\\text{req}}=\\sum_{p\\in\\text{patches}} h_p w_p N_{\\text{step}},\\qquad \\text{Cost}_{\\text{patch}} \\propto h\\cdot w\\cdot N_{\\text{step}}$$</div>\n<p>于是“长度分布”有两个维度：patch 数量的分布，与步数的分布。前者由分辨率决定，后者由采样配置决定。快通道适合短 patch、低步数的请求；慢通道适合 patch 多、步数长的高分辨率请求。问题在于，若负载中步数分布也很宽（少步采样与多步精修混跑），单个 patch 在慢通道内的驻留时间差异会被放大，大 batch 的排队效应使尾延迟进一步恶化。负载配方因此需要把“分辨率档位 × 步数档位”作为二维分桶依据，而不是只看分辨率。</p>\n<p>具体例子：一个 2048×2048 请求按 512 的 patch 边长切分得到 16 个 patch，若每 patch 走 30 步去噪，则该请求在慢通道内占据 16 条独立的采样任务；同一时刻到达的 4 个 512×512 请求各自只有 1 个 patch、步数相同，它们在快通道内以小 batch 完成。若把这 5 个请求混在一个 batch 里，GPU 的有效 batch 被 16 个 patch 的高分辨率请求拉长，4 个小请求的完成时间被推迟到与大请求同量级——这正是 patch 级分流要消除的形态。代价方面，16 个 patch 的重叠 halo 使实际计算量高于名义值，显存上每个 patch 的中间激活与请求级结果缓冲区同时驻留，显存占用随 patch 数线性上升。</p>\n\n<h3 id=\"alg-mixed-res-serve-sec-23\">二十三 · 并发与批大小：快慢通道的批参数不能同构</h3>\n<p>并发水平决定两个通道能否同时被喂饱。快通道用小 batch、低延迟 kernel，其吞吐上限受 kernel 启动开销与单 patch 计算量之比约束；慢通道用大 batch、高吞吐 kernel，其效率依赖足够多的 patch 同时在队列中。设快通道批大小为 $b_f$、慢通道为 $b_s$，在总并发 $Q$ 下，两通道的占用率为 $Q_f/b_f$ 与 $Q_s/b_s$。当 $Q$ 偏低时，慢通道凑不满 $b_s$，大 kernel 的 Tensor Core 利用率掉下来；当 $Q$ 偏高且高分辨率请求集中到达时，慢通道队列积压，而快通道空闲——负载失衡。负载配方的核心就是让 $Q_f$ 与 $Q_s$ 的比例跟随到达请求的分辨率构成动态变化，而不是固定切分。</p>\n<p>这里有一个必须写进容量规划的判断：patch 级调度把“请求级并发”换算成了“patch 级并发”，后者是前者的 $N_{\\text{patch}}$ 倍量级。调度器的队列深度、结果缓冲区的槽位数、拼接阶段的并发度都要按 patch 数而非请求数来配置，否则请求一多，patch 队列先于 GPU 成为瓶颈。延迟上，快通道的单 patch 延迟主要由 kernel 形状决定，慢通道的单 patch 延迟则包含排队等待，二者相加构成请求级 SLO 的下界。</p>\n<table class=\"mini\"><thead><tr><th>负载特征</th><th>快通道表现</th><th>慢通道表现</th><th>系统代价</th></tr></thead><tbody><tr><td>低并发、分辨率双峰</td><td>小 batch 未被喂饱，延迟低但吞吐低</td><td>凑不满大 batch，Tensor Core 利用率下降</td><td>GPU 空转，吞吐受损</td></tr><tr><td>高并发、高分辨率集中</td><td>队列空，资源闲置</td><td>patch 积压，排队时间主导尾延迟</td><td>SLO 被最慢 patch 拖垮</td></tr><tr><td>高并发、分辨率均匀偏小</td><td>饱和，吞吐接近上限</td><td>几乎无 patch，通道形同虚设</td><td>切分开销纯属浪费</td></tr></tbody></table>\n\n<h3 id=\"alg-mixed-res-serve-sec-24\">二十四 · 负载不对时会发生什么：三类可观测的退化</h3>\n<p>第一类是<strong>通道饥饿</strong>。当负载几乎全是低分辨率请求时，慢通道长期空置，patch 调度器仍按固定比例预留资源，GPU 上出现“一个通道忙、一个通道闲”的碎片化占用，整体吞吐低于直接把所有请求混批的基线。第二类是<strong>尾延迟支配</strong>。SLO 的定义是 $\\text{SLO}_{\\text{req}} = \\max_{p\\in\\text{patches}} (T_{\\text{queue},p} + T_{\\text{compute},p})$，只要有一个 patch 在慢通道里排在大 batch 之后，整个请求的完成时间就被它锁定；高分辨率请求的 patch 数越多，命中“最慢 patch”的概率越高，尾延迟分布的长尾越厚。第三类是<strong>拼接退化</strong>。当负载中高分辨率请求占比高、patch 数多时，重叠 halo 带来的额外显存与算力按 patch 数累加，若 halo 不足或融合后处理被并发挤压，拼接处出现接缝与色彩断层，图像质量下降反过来迫使重试，进一步加剧队列积压。</p>\n<p>这三类退化有共同的触发条件：到达请求的分辨率构成与调度器预设的通道配比不匹配。负载配方的作用就是在部署前用请求日志估算分辨率直方图与步数直方图，据此设定快/慢通道的批大小与资源配额，并在运行期用队列长度做反馈调整。缺少这一步，patch 级调度在错误负载上会比请求级调度更慢——因为它额外付出了切分、halo 与拼接的固定开销，却没有换来 batch 形状的改善。</p>\n\n<h3 id=\"alg-mixed-res-serve-sec-25\">二十五 · 配方落地：把负载特征映射到调度参数</h3>\n<p>落地时把负载配方写成三个可测量的输入：分辨率直方图、步数直方图、SLO 等级占比。输出是四个调度参数：patch 边长 $h_p,w_p$、快通道批大小 $b_f$、慢通道批大小 $b_s$、两通道的资源配额比。patch 边长决定 $N_{\\text{patch}}$ 与 halo 开销的平衡——边长越小，通道内 kernel 形状越规整、分流越细，但 patch 数与拼接开销上升；边长越大，切分收益越接近请求级调度。批大小则由目标 kernel 形状反推：快通道取能维持低延迟的最小批，慢通道取能填满 Tensor Core 的批，二者都不应在运行期频繁抖动，否则 kernel 重编译与队列重排会引入额外延迟。</p>\n<p>一个具体的工程判断：当高分辨率请求的 patch 数 $N_{\\text{patch}}$ 超过慢通道批大小 $b_s$ 时，该请求的 patch 会跨越多个 batch 波次，其尾延迟由最后一个波次决定，此时应优先增大 $b_s$ 或把该请求的 patch 进一步细分到快通道并行处理，而不是让它整队排在慢通道末尾。反之，当低分辨率请求的 patch 数远小于 $b_f$ 时，快通道的批利用率不足，应把多个小请求的 patch 合并进同一 batch 以摊薄 kernel 启动开销。这两条规则把负载特征直接翻译成调度动作，也是容量规划时估算 GPU 数量的依据：所需 GPU 数正比于 $\\sum_i N_{\\text{patch},i}\\cdot N_{\\text{step},i}$ 在 SLO 窗口内的积分，而非请求数。</p>\n<p>最后一点落在稳定性上：负载配方必须包含对失败模式的监控项——拼接接缝的检测、慢通道队列等待时间的分位数、快通道空闲率。当快通道空闲率持续偏高而慢通道排队时间上升时，说明负载已经偏离配方假设，此时应动态收窄慢通道准入、把部分中等分辨率 patch 导向快通道，而不是继续按原配比硬撑。patch 级调度的收益来自负载与配方的匹配，失配时它退化为一个带额外开销的请求级调度器。</p>\n\n<h3 id=\"alg-mixed-res-serve-sec-26\">二十六 · 负载配方：混合分辨率请求的适配边界与失效条件</h3>\n<p>这套 patch 级调度并非普适加速器，它的收益严格绑定在“混合分辨率请求共存、且小请求 SLO 会被长尾拖垮”的负载形态上。请求进入后按目标分辨率切分为 patch 集合并标注 SLO 等级，调度器再按分辨率与 SLO 把 patch 分到快/慢通道：快通道用小 batch、低延迟 kernel，慢通道用大 batch、高吞吐 kernel。其有效性来自一个前提——快慢通道的 patch 集合在时间上能持续供给，使两类 kernel 各自保持规整形状。若负载是单一分辨率、或分辨率差异很小，切分只增加拼接开销而不产生分流收益，此时按请求整体调度反而更省。真正适配的配方是：分辨率呈明显双峰或多峰分布，低分辨率请求占比足以填满快通道，高分辨率请求占比足以让慢通道大 batch 稳定成形；SLO 等级在请求间有真实区分度，否则分级退化为无意义标签。</p>\n<p>批大小与并发的关系是本方案的敏感参数。快通道 batch 小，单 patch 延迟低但吞吐上限受 launch 与调度开销约束；慢通道 batch 大，吞吐高但排队深度直接转化为尾延迟。请求级 SLO 由最慢 patch 支配：</p>\n<div class=\"formula\">$$\\text{SLO}_{\\text{req}} = \\max_{p\\in\\text{patches}} \\left(T_{\\text{queue},p} + T_{\\text{compute},p}\\right)$$</div>\n<p>这意味着并发上升时，慢通道队列长度是尾延迟的主控项，而非平均计算时间。一个具体例子：同一批请求中低分辨率请求被切成少量小 patch 迅速走完快通道，而某张高分辨率图被切成数十个 patch 全部落入慢通道大 batch 队列，只要其中一个 patch 排在队尾，整张图的返回时间就被它锁定，前面快通道的收益被抵消。并发越高、慢通道 batch 越大，这种“单 patch 拖垮整请求”的概率越高。因此负载配方必须约束慢通道的排队上限，或对高 SLO 请求的 patch 预留通道配额，否则吞吐与 SLO 同时受损。</p>\n<p>负载不对时的失效是双重的。其一是通道失衡：当高分辨率请求突然增多、慢通道积压而快通道空闲，GPU 资源匹配失效，快通道的小 batch kernel 占用 SM 却无活可干，慢通道则因排队过长拉高尾延迟；反之低分辨率洪峰会让慢通道大 batch 长期凑不满，Tensor Core 利用率回落。其二是切分本身的固定代价：重叠 halo 与融合后处理增加显存与算力，patch 数越多、重叠区占比越高，这部分开销越难被分流收益覆盖。边界伪影是硬约束——halo 不足或融合不当会在拼接处出现接缝与色彩断层，这要求负载配方为高分辨率请求预留额外显存余量。工程判断是：先按分辨率分布与 SLO 等级做离线分桶，估算快慢通道的 patch 到达率是否匹配各自 batch 形态；若慢通道排队时间已接近请求 SLO 余量，就应收缩高分辨率并发或改用请求级调度，而不是继续加大慢通道 batch。</p>\n<table class=\"mini\"><thead><tr><th>负载形态</th><th>通道匹配</th><th>主要代价</th></tr></thead><tbody><tr><td>分辨率双峰、SLO 分级清晰</td><td>快慢通道均能持续成批</td><td>halo 显存与拼接算力</td></tr><tr><td>单一分辨率为主</td><td>分流无收益</td><td>切分拼接纯开销</td></tr><tr><td>高分辨率突发</td><td>慢通道积压、快通道空闲</td><td>尾延迟被最慢 patch 锁定</td></tr><tr><td>低分辨率洪峰</td><td>慢通道 batch 凑不满</td><td>Tensor Core 利用率回落</td></tr></tbody></table>\n<h3 id=\"alg-mixed-res-serve-sec-27\">二十七 · 硬件档位：按 patch 通道而非请求峰值选卡</h3>\n<p>混合分辨率补丁调度的部署起点不是“单卡能跑多大分辨率”，而是“快通道与慢通道各自需要什么形状的 GPU 资源”。快通道承载低分辨率 patch，特征是 batch 小、单次 kernel 时长短、对启动开销与调度抖动敏感，需要的是高主频、低调度延迟、足够 SM 覆盖小 kernel 的卡；慢通道承载高分辨率 patch，特征是 batch 大、单次 MMA 时间长、对显存容量与 HBM 带宽敏感，需要的是大显存与高带宽。在 Blackwell 档位上，B200/B300 单卡 HBM 容量与带宽足以把慢通道的大 batch 放进显存而不触发换页，GB200/GB300 NVL72 的机柜形态则把慢通道的并行维度从卡内扩展到卡间。工程判断是：快通道优先落在与调度器同域的少量 GPU 上，减少跨节点排队；慢通道按显存容量与带宽做横向扩展。若把两类通道压在同一批卡上，慢通道的长 kernel 会占住 SM 导致快通道小 batch 排队，正是本算法要消除的互相阻塞。</p>\n<p>硬件档位与并行拓扑材料未给出具体配置，因此配方以约束形式表达而非固定型号。约束一：慢通道单卡可用显存必须容纳 <span>batch × patch 激活 × KV/中间缓冲</span> 之和，重叠 halo 带来的额外激活要计入；约束二：快通道的 kernel 时长应显著大于启动开销，否则小 batch 的低延迟优势被 launch 开销吃掉；约束三：两通道共享同一请求级缓冲区，缓冲区所在显存必须能被两条通道同时访问，跨节点时该缓冲区的放置决定拼接阶段的通信量。</p>\n\n<h3 id=\"alg-mixed-res-serve-sec-28\">二十八 · 并行拓扑：通道内并行与通道间隔离</h3>\n<p>拓扑设计要回答两个问题：慢通道内部怎么切分，快慢通道之间怎么隔离。慢通道内部，高分辨率 patch 的计算量按 <span>C ∝ H×W</span> 增长，单 patch 已足以填满单卡，因此优先用卡内张量并行而非把 patch 再切碎；当单 patch 超出单卡显存时，沿序列维做序列并行并把注意力与 GEMM 的通信压在 NVLink 域内。快通道内部，小 batch 的并行收益低，保持单卡单副本、以多副本横向扩展吞吐更划算，副本间不共享中间激活。通道间隔离的手段是资源配额而非物理分区：给快通道保留固定比例的 SM 与显存配额，使其小 batch 始终有可调度空间；慢通道使用剩余配额做大 batch。NVL72 机柜内 NVLink 5 的高带宽使慢通道的序列并行通信代价可控，而快通道副本间几乎无通信需求，二者对互联的依赖不对称，这正是拓扑上要把它们放在不同互联层的原因。</p>\n<p>一个可复现的拓扑思路：调度器与请求级缓冲区部署在一个节点组，快通道副本与调度器同组以减少 patch 入队与结果写回的往返；慢通道跨节点横向扩展，序列并行组限制在单机柜内。这样快通道的延迟路径最短，慢通道的带宽路径最宽。代价是慢通道跨节点时拼接阶段需要把 patch 结果搬回请求级缓冲区，搬运量与 patch 数成正比，patch 切得越细搬运开销越大——这构成拓扑与切分粒度的联合约束。</p>\n\n<h3 id=\"alg-mixed-res-serve-sec-29\">二十九 · 量化方案：按通道的精度分级</h3>\n<p>量化不应全模型一刀切，而应跟随通道的精度需求分级。快通道的低分辨率 patch 单次计算量小、对数值误差的容错相对高，可走更激进的低精度 GEMM 与注意力；慢通道的高分辨率 patch 单次计算量大、误差在去噪步间累积更明显，保留较高精度的权重与激活路径。判据是误差累积而非单步误差：去噪步数 <span>N_step</span> 越多，低精度引入的偏差被放大的机会越多，因此慢通道在步数高的请求上应保留精度余量。这与条目内其他片段讨论的 DiT NVFP4 混合精度量化、FP8 注意力与 GEMM 是同一批工具，此处只给通道级的分级原则：精度档位作为 patch 队列的一个标签参与调度，而非部署期的全局常量。</p>\n<div class=\"formula\">$$\\text{Cost}_{\\text{patch}} \\propto h\\cdot w\\cdot N_{\\text{step}},\\quad \\text{SLO}_{\\text{req}} = \\max_{p\\in\\text{patches}} \\left(T_{\\text{queue},p} + T_{\\text{compute},p}\\right)$$</div>\n<p>把精度标签并入上式：<span>T_compute,p</span> 随精度档位变化，低精度缩短单 patch 计算时间但可能增加返工或质量补偿步数；<span>T_queue,p</span> 随通道负载变化。调度器在分配 patch 时同时决定通道与精度档位，等价于在 SLO 约束下解一个二维分配问题。代价侧：低精度降低显存占用与带宽压力，使慢通道能塞进更大 batch，但若精度不足导致拼接后可见质量退化，返工成本会以整请求为单位放大，远超单 patch 节省的时间。工程判断是快通道激进、慢通道保守，且精度档位随请求 SLO 等级联动——高 SLO 等级请求的 patch 即使落在快通道也保留精度余量。</p>\n\n<h3 id=\"alg-mixed-res-serve-sec-30\">三十 · KV 策略：patch 级缓冲与请求级拼接缓冲分离</h3>\n<p>本算法在采样阶段内部按 patch 分流，因此缓存要分两层管理。第一层是 patch 级工作缓冲：每个 patch 独立采样去噪，其注意力 KV 或等价中间状态只在该 patch 的生命周期内有效，patch 完成即释放，生命周期短、复用率为零，策略应是“即用即弃 + 池化复用”，避免按请求维度长期持有。第二层是请求级拼接缓冲：各通道写回的 patch 结果按请求聚合，等待全部 patch 完成后拼接与 VAE 解码，这一层的容量由并发请求数与单请求 patch 数决定，是显存占用的主要来源。两层混用会把短生命周期的 patch 缓冲长期占住，直接压缩慢通道的 batch 空间。</p>\n<p>重叠 halo 使第一层的实际占用高于名义 patch 尺寸：每个 patch 需携带边界重叠区，重叠比例决定额外显存与算力。halo 不足则拼接处出现接缝与色彩断层，halo 过大则 patch 有效计算占比下降。可复现的做法是把 halo 宽度作为与 patch 尺寸联动的参数，按模型感受野与 VAE 上采样倍率设定下限，并在拼接阶段用融合后处理消除残余差异。代价量化：halo 使单 patch 计算量按 <span>(h+2δ)(w+2δ)</span> 放大，δ 为 halo 宽度，显存与算力同步上升；请求级尾延迟则由最慢 patch 决定，若某 patch 因 halo 膨胀落入慢通道排队，整个请求的 SLO 被它拖住。</p>\n\n<h3 id=\"alg-mixed-res-serve-sec-31\">三十一 · 调度参数：通道配额、批大小与尾延迟保护</h3>\n<p>调度参数的核心是三个旋钮：快慢通道的 SM/显存配额比例、两通道各自的批大小上下限、以及针对尾延迟的保护阈值。配额比例决定两通道在负载失衡时的弹性：快通道配额过低则小请求 SLO 被慢通道挤占，过高则慢通道 batch 填不满、吞吐下降。批大小上下限要与 kernel 形状规整性绑定——快通道小 batch 保证低延迟，慢通道大 batch 保证 Tensor Core 利用率高于混 batch；上下限设死可防止调度器在瞬时负载下把快通道 batch 撑大而破坏其延迟特性。尾延迟保护阈值作用于请求级：当某请求的已完成 patch 比例落后于其 SLO 等级对应的进度时，调度器提升其剩余 patch 的通道优先级或临时改派到快通道，避免最慢 patch 独吞等待时间。</p>\n<p>伪代码思路：patch 入队时携带 (分辨率档, SLO 等级, 精度档, 请求进度)；调度循环每轮先按配额取快通道可容纳的 patch 集合，再以剩余配额填充慢通道大 batch；对每个请求检查进度落后量，超阈值则把其待处理 patch 标记为优先。代价侧：优先级改派会让慢通道 batch 出现空洞，降低其形状规整度与吞吐；配额与阈值的联合调参空间大，负载失衡时资源匹配失效会使吞吐与 SLO 同时受损。可复现的配置思路是先固定配额比例与批大小上下限，仅调尾延迟阈值观察请求级 SLO 分布，再反向调配额，避免两个维度同时变动导致归因困难。</p>\n\n<h3 id=\"alg-mixed-res-serve-sec-32\">三十二 · 可复现配置思路：从约束到参数的落地顺序</h3>\n<p>把上述决策串成一条可复现的落地顺序。第一步定切分粒度与 halo：由模型感受野与 VAE 倍率确定 halo 下限，由慢通道单卡显存确定 patch 尺寸上限，二者夹出可行区间。第二步定通道配额：以快通道能稳定容纳其目标并发小请求为下限，以慢通道 batch 能填满其 kernel 形状为下限，取二者交集。第三步定量化档位：快通道取激进档、慢通道取保守档，高 SLO 等级请求的 patch 保留精度余量。第四步定 KV 两层策略：patch 级缓冲池化即弃，请求级拼接缓冲按并发请求数 × patch 数预留。第五步定调度参数：批大小上下限先固定，尾延迟阈值单独调。每一步都以显存与带宽为硬约束，以 <span>SLO_req</span> 的尾延迟分布为验收指标。</p>\n<p>工程判断落在最后一步的取舍上：patch 切得越细，快慢通道的 kernel 形状越规整、大小请求越不易互相阻塞，但拼接与 halo 开销、请求级尾延迟的支配效应同步放大；切得越粗，拼接简单、尾延迟可控，但通道分级的收益被削弱。配置思路的本质是在这条曲线上选点，而非追求某一维最优。当慢通道排队成为尾延迟主因时，优先调尾延迟保护阈值与配额，而不是继续细化 patch——细化只会增加被最慢 patch 支配的候选数量。</p>\n\n<h3 id=\"alg-mixed-res-serve-sec-33\">三十三 · 配方边界：通道配比、halo 预算与尾延迟闸门</h3>\n<p>本方案的可复现配置思路不是给出一组固定超参，而是给出三个必须现场标定的量：快慢通道的算力配比、重叠 halo 的显存预算、以及请求级尾延迟的准入闸门。快通道用小 batch 低延迟 kernel，慢通道用大 batch 高吞吐 kernel，两者共享同一批 SM，因此配比本质上是 SM 时间片的划分。设快通道占用比例为 $\\rho$，则慢通道有效吞吐近似按 $(1-\\rho)$ 缩放，而快通道排队延迟随 $\\rho$ 增大而下降；工程上应把 $\\rho$ 标定到“小请求 SLO 恰好满足、慢通道吞吐损失可接受”的拐点，而非取固定值。量化方案与 KV 策略在本方案中不是独立旋钮：patch 级独立采样去噪意味着每个通道的激活分布不同，快通道因 batch 小、kernel 形状规整，更适合激进低精度路径；慢通道大 batch 下数值累积误差更敏感，需保留更高精度或采用分通道差异化量化，否则拼接处的色彩断层会被误判为 halo 不足。</p>\n<p>halo 预算直接决定显存与算力代价。重叠 patch 使实际计算量放大为</p>\n<div class=\"formula\">$$\\text{Cost}_{\\text{patch}} \\propto h\\cdot w\\cdot N_{\\text{step}}\\cdot\\left(1+\\frac{2\\delta}{h}\\right)\\left(1+\\frac{2\\delta}{w}\\right)$$</div>\n<p>其中 $\\delta$ 为单边 halo 宽度。halo 不足则接缝与色彩断层出现，halo 过大则显存与算力按面积平方级上升，且慢通道大 batch 下这部分开销被同步放大。可复现的做法是把 $\\delta$ 与融合后处理的感受野绑定标定，而不是凭经验取值；当显存逼近上限时，优先缩小慢通道 batch 而非削减 halo，因为削减 halo 的失效是可见的画质事故，缩小 batch 只损失吞吐。</p>\n<p>尾延迟闸门是本配方最容易被忽略的失效条件。请求级 SLO 由最慢 patch 支配：</p>\n<div class=\"formula\">$$\\text{SLO}_{\\text{req}} = \\max_{p\\in\\text{patches}} \\left(T_{\\text{queue},p} + T_{\\text{compute},p}\\right)$$</div>\n<p>慢通道大 batch 排队时，单个 patch 即可拖垮整个请求。因此调度器需对每个请求维护“剩余最慢 patch”的预测，当预测超出该请求 SLO 等级时，将该 patch 降级插入快通道或拆分为更小 patch 以缩短单 patch 计算时间——这是用吞吐换尾延迟的显式决策，必须记录在调度日志中以便复现。失效边界有三条：快慢通道负载失衡导致 GPU 资源匹配失效，吞吐与 SLO 同时受损；patch 级队列与拼接逻辑复杂引发调度失误；以及混合负载中高分辨率请求占比过高时，慢通道排队深度超过闸门可调节范围，此时应拒绝或降级高分辨率请求，而非继续堆叠 batch。</p>\n<table class=\"mini\"><thead><tr><th>标定量</th><th>失效表现</th><th>系统代价</th></tr></thead><tbody><tr><td>通道算力配比 $\\rho$</td><td>小请求 SLO 失守或慢通道吞吐塌陷</td><td>SM 时间片争用，整体吞吐下降</td></tr><tr><td>halo 宽度 $\\delta$</td><td>接缝、色彩断层</td><td>显存与算力按面积放大</td></tr><tr><td>尾延迟闸门</td><td>单 patch 拖垮请求 SLO</td><td>降级分流带来吞吐损失</td></tr></tbody></table>\n<h3 id=\"alg-mixed-res-serve-sec-34\">三十四 · 显存账：patch 缓冲与 halo 的乘性开销</h3>\n<p>patch 级调度在显存上做的第一件事，是把一个请求的激活峰值从「整图一次」变成「若干 patch 并行在飞」。看起来是省，实际是加。请求级缓冲区要为每个 patch 保留去噪中间结果直到拼接完成，重叠 halo 又让每个 patch 的有效像素面积大于其名义面积。设 patch 名义边长 $p$、halo 宽度 $r$，则单 patch 的像素数为 $(p+2r)^2$ 而非 $p^2$，面积膨胀因子为</p>\n<div class=\"formula\">$$\\eta_{\\text{halo}}=\\left(1+\\frac{2r}{p}\\right)^2$$</div>\n<p>$r$ 由 DiT 的感受野与 VAE 解码的块边界共同决定，$p$ 越小 $\\eta$ 越接近 1 但 patch 数量 $N_p=\\lceil H/p\\rceil\\cdot\\lceil W/p\\rceil$ 上升，请求级缓冲区的条目数随之上升。真正的显存代价是两者相乘：总缓冲 $\\propto N_p\\cdot\\eta_{\\text{halo}}\\cdot p^2\\cdot d$，其中 $d$ 为潜空间通道维度。工程上这意味着存在一个最优 $p$：$p$ 太大则快通道失去意义（单 patch 已接近整图，小 batch 低延迟 kernel 无从谈起），$p$ 太小则 halo 占比与队列条目数同时膨胀。在 Blackwell 上这条曲线还被 TMEM 放大——tcgen05 MMA 的累加器占用 TMEM 列，patch 形状越碎，单次 MMA 的 $M$ 维越难填满 128 行的自然粒度，TMEM 利用率下降，等效于为同样计算量预留更多片上资源。显存先崩的位置通常不是权重，而是请求级缓冲区里那些「已完成但尚未拼接」的 patch 潜变量：它们必须驻留到最慢 patch 到齐，驻留时间由尾延迟而非平均延迟决定。</p>\n\n<h3 id=\"alg-mixed-res-serve-sec-35\">三十五 · 带宽账：拼接与融合后处理的搬运量</h3>\n<p>patch 调度的带宽代价分三段：patch 写入请求级缓冲区、拼接时的重叠区融合、VAE 解码前的潜变量重整。三段都是 HBM 往返，且都不产生有用 FLOPs。以潜变量写回为例，单请求搬运量为 $N_p\\cdot\\eta_{\\text{halo}}\\cdot p^2\\cdot d\\cdot b$ 字节（$b$ 为每元素字节数），NVFP4 下 $b$ 减半但 halo 膨胀不变，因此量化对这一段带宽的改善是线性的、无法抵消 patch 数量增长。融合后处理更贵：重叠区需要按权重加权平均或做羽化，读两次写一次，搬运量约为非重叠区的 3 倍乘以 halo 面积占比。当 $N_p$ 随分辨率平方增长时，这段带宽按 $O(HW)$ 走，与 DiT 主计算同阶，但它没有 Tensor Core 加速，纯靠 SM 的 load/store 与 L2。Blackwell 的 HBM 带宽虽高，这一段却容易把 L2 打成瓶颈：patch 缓冲区若跨多个 SM 的私有工作集，重叠区读写会在 L2 上反复换入换出。工程判断是让同一请求的相邻 patch 尽量落在同一 GPC 内，用 L2 局部性吃掉融合读写，代价是调度器要维护 patch 到 SM 的亲和映射，队列逻辑复杂度上升——这正是失败模式里「调度失误」的来源之一。</p>\n\n<h3 id=\"alg-mixed-res-serve-sec-36\">三十六 · 通信账：分离式部署下 patch 的跨节点流动</h3>\n<p>在分离式预填/解码或 PD 分离的扩散服务里，patch 级调度会把通信模式改掉。请求级调度时，一个请求的潜变量只在阶段边界搬运一次；patch 级调度后，patch 可以在不同节点上独立去噪，拼接发生在某一侧，于是产生两类流量：patch 潜变量的跨节点汇聚，以及拼接后潜变量回传解码节点的单次大传输。前者是 $N_p$ 个小消息，后者是 1 个大消息。NVLink 5 与 NCCL 对大消息友好，对小消息的固定开销敏感，$N_p$ 上去以后汇聚段会成为通信尾延迟的贡献者。NIXL 这类点对点传输能把 patch 汇聚做成 RDMA 直写，绕开集合通信的同步屏障，但要求调度器预先知道每个 patch 的落点，即 patch 到节点的静态或半静态映射。跨 NVL72 机柜时，patch 汇聚的拓扑跨度决定了它走 NVLink 域内还是域间，域间带宽下降会让「patch 独立去噪」的并行收益被通信吃掉。这里的工程判断是：只有当单 patch 计算时间显著大于其汇聚传输时间时，patch 级跨节点并行才划算，否则应把同一请求的 patch 收敛到同一 NVLink 域内，用域内高带宽换掉域间不确定性。</p>\n\n<h3 id=\"alg-mixed-res-serve-sec-37\">三十七 · 功耗与利用率：快慢通道的能效错配</h3>\n<p>快通道用小 batch 低延迟 kernel，慢通道用大 batch 高吞吐 kernel，两者在同一 GPU 上共存时，功耗曲线不是简单叠加。小 batch kernel 的 SM 占用率低但频率请求高，大 batch kernel 占用率高但受功耗墙约束会降频；当快通道的短任务频繁插入慢通道的长任务之间，SM 的占用在时间上被切碎，DVFS 在升频与降频之间来回，能效落在两个通道各自最优点的下方。设快通道占空比为 $\\alpha$，则混合负载下的有效能效近似为</p>\n<div class=\"formula\">$$\\text{Eff}_{\\text{mix}}\\approx\\frac{1}{\\alpha/\\text{Eff}_{\\text{fast}}+(1-\\alpha)/\\text{Eff}_{\\text{slow}}}+\\Delta_{\\text{DVFS}}(\\alpha)$$</div>\n<p>$\\Delta_{\\text{DVFS}}$ 是频率切换带来的惩罚项，$\\alpha$ 越接近 0.5 惩罚越大——这解释了为什么混合负载在中等高低分辨率比例下最容易出现「吞吐与 SLO 同时受损」。缓解手段不是调 batch，而是给快通道划出固定的 SM 配额与频率下限，让慢通道在剩余配额内跑大 batch，把 DVFS 的抖动限制在配额边界而非全局。代价是慢通道的 batch 上限被配额压缩，大请求的吞吐下降，需要用 patch 队列深度换回来：慢通道队列越深，单次大 batch 的有效性越高，但排队时间直接进入请求级尾延迟。</p>\n\n<h3 id=\"alg-mixed-res-serve-sec-38\">三十八 · 尾延迟：最慢 patch 支配与队列深度的取舍</h3>\n<p>请求级 SLO 由最慢 patch 决定，这是 patch 调度的结构性弱点。$\\text{SLO}_{\\text{req}}=\\max_{p}(T_{\\text{queue},p}+T_{\\text{compute},p})$ 中，$T_{\\text{queue},p}$ 对慢通道 patch 而言是排队等大 batch 凑齐的时间，$T_{\\text{compute},p}$ 是大 batch kernel 的执行时间。两者都随慢通道队列深度上升，但方向相反：队列越深，batch 越大，$T_{\\text{compute},p}$ 摊薄但 $T_{\\text{queue},p}$ 上升。存在一个使 $\\max$ 最小的队列深度，它由快慢通道的到达率比与 patch 计算时间分布共同决定。尾延迟的另一个来源是 patch 之间的完成时间离散：同一请求的 patch 若被分到不同通道（例如边缘 patch 因分辨率标注不同走了快通道），拼接要等两边都完成，快通道的低延迟优势被慢通道抵消。稳定性技巧里的重叠 patch 与融合后处理在这里也有代价——halo 越大，单 patch 计算越久，尾延迟的绝对量越大。工程上可行的做法是把同一请求的所有 patch 绑定到同一通道，用请求级而非 patch 级的通道选择换取尾延迟的可预测性，代价是快通道对小请求的吸引力下降，混合负载的吞吐改善被削弱。</p>\n\n<h3 id=\"alg-mixed-res-serve-sec-39\">三十九 · 规模上去以后先崩的位置</h3>\n<p>把上述几条按规模排序，先崩的通常不是算力而是请求级缓冲区的驻留显存与拼接带宽。理由：DiT 主计算随 $HW$ 增长但有 Tensor Core 与 NVFP4 摊薄，patch 缓冲与 halo 融合是纯搬运，随 $N_p$ 线性甚至超线性增长，且不受量化收益。第二崩的是慢通道队列深度带来的尾延迟，因为它是 $\\max$ 运算，规模越大分布尾部越厚，SLO 违约从个别请求扩散为系统性。第三崩的才是通信，且只在跨 NVLink 域部署时显现。功耗与 DVFS 抖动是放大器而非独立瓶颈。据此的工程判断是：patch 调度的规模上限应由「单请求缓冲驻留量 × 并发请求数」与「拼接融合带宽占 HBM 带宽比例」两个约束共同确定，前者决定能开多少并发，后者决定 patch 边长 $p$ 的下界；在这两个约束内，快慢通道的配额划分才是可调的旋钮，超出约束后调 batch 与队列深度只是把崩溃点从显存搬到尾延迟。</p>\n\n<h3 id=\"alg-mixed-res-serve-sec-40\">四十 · 规模上去以后，先崩的是尾延迟而不是平均吞吐</h3>\n<p>把 patch 级调度放到生产规模，代价结构会从“算得快不快”转成“谁在等谁”。patch 的计算量按 <span class=\"formula\">$$\\text{Cost}_{\\text{patch}} \\propto h\\cdot w\\cdot N_{\\text{step}}$$</span> 增长，而请求级 SLO 是各 patch 时延的最大值：<span class=\"formula\">$$\\text{SLO}_{\\text{req}} = \\max_{p\\in\\text{patches}} \\left(T_{\\text{queue},p} + T_{\\text{compute},p}\\right)$$</span>。这个 max 是整套方案的系统性弱点：快通道里几十个低分辨率 patch 早已算完，只要慢通道里还有一个高分辨率 patch 卡在大 batch 队列里，整个请求就仍然不可返回。规模扩大时，慢通道的排队时间随并发线性上升，而 max 直接把它抬进请求 SLO，于是平均吞吐看起来还在涨，尾延迟先崩。工程上必须把慢通道的排队时延当作一等指标来控，而不是只看通道利用率。</p>\n<p>显存与带宽的代价来自两处叠加。其一，重叠 halo 让 patch 的有效像素面积大于名义面积，重叠比例越高，DiT 的激活与中间张量按面积放大，显存占用与 HBM 带宽同步上涨；halo 不足则拼接处出现接缝与色彩断层，属于不可接受的画质失效，所以这部分开销不能靠“少切一点”省掉。其二，patch 结果要写回请求级缓冲区并在全部完成后拼接、VAE 解码，缓冲区按请求驻留，混合负载下高分辨率请求的缓冲区尺寸远大于低分辨率请求，显存碎片化严重。规模上去后，先撞墙的往往是缓冲区容量而非算力：调度器为了保住快通道的低延迟，会限制慢通道并发，一旦慢通道并发被压到低于其吞吐拐点，大 batch kernel 的 Tensor Core 利用率回落，快慢通道的收益同时被侵蚀。</p>\n<p>通信与功耗在单机内不是主矛盾，跨节点才显现。patch 级队列把同一请求的 patch 分散到不同通道、可能落到不同 GPU，各通道独立采样去噪后需要把结果汇聚回请求级缓冲区，这引入一次 all-to-all 性质的搬运；patch 越小、切分越细，搬运次数与元数据开销越高，而 NVLink 域内的带宽虽宽，跨域时延却会直接进入 <span class=\"formula\">$$T_{\\text{queue},p}$$</span>。功耗侧的特征是通道间负载失衡：快通道小 batch kernel 频繁启动、慢通道大 batch kernel 长时间占用 SM，两者的功耗曲线不同步，整卡功耗被慢通道的持续高占用拉高，而快通道的短脉冲又难以被功率管理平滑，结果是能效比在混合负载下反而低于统一 batch。规模上限因此不是单一数字，而是由“慢通道排队时延 ≤ 请求 SLO 余量”“缓冲区显存 ≤ 单卡可用”“跨域搬运时延 ≤ patch 计算时延”三条约束共同截断，任一先到即失效。</p>\n<table class=\"mini\"><thead><tr><th>规模放大时的失效点</th><th>触发条件</th><th>系统表现</th></tr></thead><tbody><tr><td>尾延迟</td><td>慢通道排队时间超过 SLO 余量</td><td>平均吞吐仍升，P99 请求超时</td></tr><tr><td>显存</td><td>重叠 halo 与请求级缓冲区叠加</td><td>慢通道并发被压，大 batch 利用率回落</td></tr><tr><td>通信</td><td>patch 跨通道/跨卡汇聚</td><td>搬运时延进入单 patch 关键路径</td></tr><tr><td>负载失衡</td><td>快慢通道 patch 比例漂移</td><td>GPU 资源匹配失效，吞吐与 SLO 同损</td></tr></tbody></table>\n<p>一个具体的判断例子：当混合负载中高分辨率请求占比上升，慢通道队列长度增长快于快通道清空速度，调度器若继续按分辨率静态分通道，慢通道会持续积压而快通道空转，此时正确动作是把部分中等分辨率 patch 动态降级到快通道、或对慢通道做请求级准入控制，而不是加大慢通道 batch——加大 batch 只会把单个 patch 的完成时间推后，max 进一步恶化。这也解释了为什么该方案的上限受“patch 切分与拼接开销”约束而非受算力约束：切分越细，调度自由度越高但 halo 与汇聚开销越大；切分越粗，越接近按请求整体调度，快慢通道的隔离收益消失。规模化的工程判断是先把慢通道排队时延与缓冲区显存做成可观测的硬约束，再谈吞吐。</p>\n<h3 id=\"alg-mixed-res-serve-sec-41\">四十一 · 精度失败：halo 不足与融合后处理的数值放大</h3>\n<p>混合分辨率补丁调度在数值层面的失败几乎全部集中在拼接边界。机制上，每个 patch 独立采样去噪，其去噪轨迹只看到自身像素邻域；若重叠 halo 宽度小于 DiT 有效感受野，patch 边缘的 latent 统计量（均值、方差）与内部不一致，拼接后表现为接缝、色带与高频振铃。更隐蔽的是融合后处理的数值放大：重叠区常用加权平均或 feathered blend，若权重在 FP8/NVFP4 量化后的 patch 输出上直接做线性混合，低精度尾数误差会在权重归一化时被放大，形成沿边界的周期性条纹。</p>\n<p>诊断量应落在边界一致性上，而非整图 PSNR。对相邻 patch 的重叠区取差值图，计算边界带能量占比：</p>\n<div class=\"formula\">$$R_{\\text{seam}}=\\frac{\\sum_{(i,j)\\in \\partial\\Omega}\\lVert x_i-x_j\\rVert^2}{\\sum_{(i,j)\\in \\Omega}\\lVert x_i-x_j\\rVert^2}$$</div>\n<p>当 $R_{\\text{seam}}$ 相对同分辨率整图推理的基线出现量级抬升时，优先怀疑 halo 宽度与融合权重，而不是量化本身。工程代价是显存与算力：halo 从 $h$ 扩到 $2h$，patch 有效像素按 $(w+2h)(h+2h)$ 增长，重叠区重复计算直接抬高慢通道的算力占用，在显存紧张时挤压 KV/特征缓冲。具体例子：一张高分辨率请求被切成 4×4 patch、halo 取一个潜空间像素时接缝明显，扩到两个潜空间像素并改用按距离衰减的融合核后接缝能量回落——代价是慢通道每 patch 计算量上升，尾延迟随之变长。</p>\n\n<h3 id=\"alg-mixed-res-serve-sec-42\">四十二 · 显存失败：重叠 patch 与请求级缓冲区的叠加占用</h3>\n<p>OOM 在本算法里不是单点爆发，而是三份占用叠加：重叠 halo 带来的重复激活、请求级拼接缓冲区、以及快慢通道各自的采样中间态。机制上，patch 结果写回请求级缓冲区意味着整张图的 latent 必须常驻，直到最慢 patch 完成；若调度器同时放行过多高分辨率请求，缓冲区按请求数线性增长，而慢通道大 batch 又按 batch 数放大激活。二者相乘，显存峰值出现在“慢通道 batch 已满、快通道仍在补位”的交叠时刻。</p>\n<p>可监控的量是请求级缓冲区的驻留 patch 数与慢通道 batch 占用的乘积，设上限 $M_{\\text{buf}}$，准入控制写成：</p>\n<div class=\"formula\">$$\\sum_{r\\in \\text{active}} \\text{patches}(r)\\cdot s_{\\text{patch}} + B_{\\text{slow}}\\cdot a_{\\text{act}} \\le M_{\\text{buf}}$$</div>\n<p>其中 $s_{\\text{patch}}$ 为单 patch latent 字节数，$a_{\\text{act}}$ 为单样本激活。代价判断很直接：缓冲区每多驻留一个高分辨率请求，就少一份给慢通道 batch 的余量，吞吐与尾延迟同时受压。具体例子：当多个高分辨率请求同时进入、patch 集合尚未消费完，慢通道 batch 被迫缩小以腾出缓冲区，大 batch 高吞吐 kernel 退化为小 batch，Tensor Core 利用率下降——这正是 OOM 前的典型前兆，应在显存到达硬上限前由准入控制拦截，而不是等分配失败后重试。</p>\n\n<h3 id=\"alg-mixed-res-serve-sec-43\">四十三 · 批抖动与路由不均：快慢通道的负载失衡</h3>\n<p>批抖动的根源是 patch 到达率与通道消费率不匹配。机制上，快通道用小 batch 低延迟 kernel，其 batch 填充依赖低分辨率 patch 的持续供给；一旦高分辨率请求集中到达，patch 切分后大量 patch 被标注为慢通道，快通道队列见底，kernel 启动间隔被拉长，已入队的小请求 patch 反而等不到合并机会。反向失衡同样致命：慢通道 batch 长期填不满，大 batch kernel 形状退化，吞吐掉回混 batch 水平。</p>\n<p>诊断指标是两通道的 batch 填充率与排队时长之比，定义失衡度：</p>\n<div class=\"formula\">$$\\delta=\\left|\\frac{\\bar{b}_{\\text{fast}}/b^{\\star}_{\\text{fast}}}{\\bar{b}_{\\text{slow}}/b^{\\star}_{\\text{slow}}}-1\\right|$$</div>\n<p>$\\delta$ 持续偏大说明路由把 patch 推向了错误通道，而非负载本身波动。路由不均还有一层来源：SLO 等级标注过粗，同一分辨率下不同紧迫度的 patch 被塞进同一队列，快通道被本可延迟的 patch 占满，真正紧的 patch 排在后面。代价体现在尾延迟尖刺上——快通道本应压低的 $T_{\\text{queue},p}$ 被无效占用抬高，请求级 SLO 由最慢 patch 支配的公式立刻显形。具体例子：一批中等分辨率请求被统一标注为高 SLO 而全部路由到快通道，快通道小 batch 被打满、慢通道空转，整体吞吐下降且高分辨率请求尾延迟抬升；把标注改为按 patch 分辨率与请求剩余时延双条件路由后，两通道填充率回到同一量级。</p>\n\n<h3 id=\"alg-mixed-res-serve-sec-44\">四十四 · 尾延迟尖刺：最慢 patch 支配与慢通道排队</h3>\n<p>尾延迟尖刺的机制是请求级 SLO 的 max 结构：$\\text{SLO}_{\\text{req}}=\\max_{p}(T_{\\text{queue},p}+T_{\\text{compute},p})$，任何一个 patch 在慢通道排到大 batch 尾部，整个请求就被它拖住。尖刺通常不是计算慢，而是排队：慢通道为追求吞吐把 batch 攒大，攒批窗口内的 patch 全部等待，窗口末端到达的 patch 恰好赶上最长等待。这与按请求整体调度的服务不同——后者至少能把整个请求作为一个调度单元排序，patch 级调度把等待打散到每个 patch 上，最慢者不可预测。</p>\n<p>可监控的量是每请求 patch 完成时间的离散度与慢通道排队深度。工程上常用的缓解是给慢通道设排队上限并对超限 patch 降级到快通道小 batch 抢跑，代价是牺牲部分吞吐换尾延迟；另一种是重叠 halo 之外再做结果预取，让拼接在最后一个 patch 完成前就开始，压缩 $T_{\\text{compute},p}$ 的可见部分。具体例子：一个高分辨率请求的 16 个 patch 中 15 个已在缓冲区内，最后一个 patch 因慢通道攒批多等了一个窗口，请求整体 SLO 被突破；把该 patch 的 SLO 等级在排队超阈值后动态提升、改走快通道，尾延迟尖刺消失，代价是慢通道 batch 少了一个样本、吞吐略降。</p>\n\n<h3 id=\"alg-mixed-res-serve-sec-45\">四十五 · 监控面与回滚：可观测信号与降级路径</h3>\n<p>监控必须覆盖三个层面，缺一层就无法定位是精度、显存还是调度问题。patch 层看边界能量比 $R_{\\text{seam}}$、单 patch 计算时长分布、halo 覆盖率；通道层看快慢通道 batch 填充率、失衡度 $\\delta$、排队深度与攒批窗口命中率；请求层看 patch 完成时间离散度、拼接缓冲区驻留量、SLO 突破计数。三者对齐时间戳后，尾延迟尖刺能直接归因到具体通道的排队事件，而不是笼统的“GPU 慢”。</p>\n<p>回滚路径要按失败类型分级，不能一刀切回整图推理。精度问题回滚 halo 宽度与融合核，属于配置级回滚，代价是慢通道算力上升；OOM 回滚准入阈值与缓冲区上限，属于调度级回滚，代价是并发请求数下降；批抖动与路由不均回滚路由标注规则，属于策略级回滚；尾延迟尖刺回滚攒批窗口与降级阈值。关键工程判断是：patch 级调度的收益来自通道分离，回滚时优先保住通道分离、只调参数，直接退回整图混 batch 会把已经拿到的 Tensor Core 利用率与 SLO 改善一并丢掉。具体例子：当 $R_{\\text{seam}}$ 与尾延迟同时恶化，先查是否因扩 halo 挤压了慢通道 batch 导致排队变长——两个症状同源，回滚 halo 而非回滚整个调度器才是正确动作。</p>\n\n<h3 id=\"alg-mixed-res-serve-sec-46\">四十六 · 失败模式与诊断：从接缝、尾刺到通道失衡</h3>\n<p>这套 patch 级分级调度在混合分辨率负载下把吞吐与 SLO 同时拉起来，代价是它把风险从\"请求级\"下推到了\"patch 级\"——一个 patch 出错，整张图就废；一个 patch 卡住，整个请求的 SLO 就崩。诊断必须围绕这条新的故障链设计。第一类失效是精度类：切分与拼接引入边界伪影，重叠 halo 不足或融合后处理权重不当，拼接处出现接缝与色彩断层。根因不在采样本身，而在各通道独立去噪——快通道与慢通道的 kernel 形状、batch 组成不同，同一请求相邻 patch 若落在不同通道，去噪轨迹的数值细节（如 timestep 嵌入的舍入、累积误差）不完全一致，接缝两侧色调漂移。诊断手段是离线比对：对同一请求分别走\"整图单通道\"与\"patch 分级\"两条路径，在拼接边界带取像素差，若边界带误差显著高于 patch 内部，即为 halo 或融合问题；工程上把 halo 宽度与融合核作为可调参数，按边界误差分布而非目测调参。代价是重叠 patch 直接抬高显存与算力：设 halo 边长为 <span>o</span>、patch 边长为 <span>s</span>，重叠带来的额外计算比例约为 <span>(1+2o/s)²−1</span>，o/s 取 1/8 时已近 50% 的冗余像素计算，这部分算力必须计入容量规划，否则慢通道的实际吞吐会被高估。</p>\n<p>第二类是调度类失效，核心是尾延迟尖刺。请求级完成时间由最慢 patch 支配，这正是 <span>SLO<sub>req</sub> = max<sub>p∈patches</sub>(T<sub>queue,p</sub> + T<sub>compute,p</sub>)</span> 的含义：慢通道大 batch 排队时，单个 patch 的排队项就能拖垮整个请求。监控上不能只看请求级 P99，必须把 <span>T<sub>queue,p</sub></span> 与 <span>T<sub>compute,p</sub></span> 分通道打点，并对每个请求记录\"最慢 patch 所属通道与排队深度\"。判据是：若某请求的尾刺与其最慢 patch 的排队时间高度相关，说明问题在通道容量而非 kernel；若与 compute 相关，则检查该通道是否被超规格 patch（分辨率越级）污染。批抖动是同一根因的另一面：快通道为保低延迟用小 batch，慢通道为大吞吐攒大 batch，当高分辨率请求突增，慢通道队列变长而快通道空闲，GPU 资源匹配失效，吞吐与 SLO 同时受损——表现为快通道利用率下滑与慢通道排队同时出现。诊断信号是两通道的 batch 组成与 SM 占用率出现持续背离，此时应触发通道配额再平衡，而非简单扩容。</p>\n<p>第三类是显存与路由类。OOM 在 patch 方案里有独特形态：请求级缓冲区按 patch 结果累积写回，重叠 halo 与多通道中间激活叠加，峰值显存出现在\"拼接前全部 patch 驻留\"的时刻，而非单次采样。监控应在请求级缓冲区分配处设水位线，并对并发请求数按 patch 总数而非请求数限流。路由不均则表现为分辨率分级失效：若调度器按请求标注的 SLO 而非实际 patch 分辨率分流，低 SLO 的高分辨率请求会被塞进快通道，小 batch kernel 处理超大 patch，Tensor Core 利用率骤降并挤占真正的小请求。诊断靠\"通道内 patch 分辨率分布\"直方图，偏离预期即判定路由错配。回滚策略要分层：精度问题回滚 halo 与融合参数，不动调度；尾刺与批抖动回滚通道配额与 batch 上限；OOM 回滚并发限流阈值；路由错配回滚分级规则本身。每一层都保留\"整图单通道\"作为兜底路径，按请求 SLO 等级决定是否启用，使故障时能以吞吐换稳定，而不是让整条服务链一起失效。</p>\n<table class=\"mini\"><thead><tr><th>失效模式</th><th>可观测信号</th><th>回滚动作</th></tr></thead><tbody><tr><td>边界伪影</td><td>拼接边界带像素差高于 patch 内部</td><td>加大 halo、改融合核</td></tr><tr><td>尾延迟尖刺</td><td>最慢 patch 排队项主导请求 P99</td><td>调慢通道 batch 上限与配额</td></tr><tr><td>批抖动</td><td>快通道空闲与慢通道排队并存</td><td>通道配额再平衡</td></tr><tr><td>OOM</td><td>请求级缓冲区水位逼近上限</td><td>按 patch 总数限并发</td></tr><tr><td>路由不均</td><td>通道内分辨率分布偏离预期</td><td>回滚分级规则，启用整图兜底</td></tr></tbody></table>\n<h3 id=\"alg-mixed-res-serve-sec-47\">四十七 · 对照轴：调度发生在哪一层</h3>\n<p>把相邻算法摆到同一张图上，第一条对照轴不是精度、不是缓存，而是<strong>调度决策的粒度</strong>。混合分辨率补丁调度把决策下沉到 patch：一个请求被切成 patch 集合，每个 patch 带分辨率标签与 SLO 等级，各自进快/慢通道队列。与之相对，按请求整体调度的服务方案（连续批处理、请求级准入与优先级队列）只在请求边界做决策，batch 里一旦混入高分辨率请求，整个 batch 的 kernel 形状被最大张量支配，小请求只能等。第三条轴是阶段级扩散服务流水：它按 stage 拆 DiT / VAE / 后处理，决策发生在流水段边界，粒度比 patch 粗、比请求细。三者的差别可以写成一句判断：<em>决策粒度越细，隔离性越好，但拼接与队列状态管理的代价越高</em>。补丁调度是三者中唯一在采样阶段内部做分流的方案，这也决定了它的代价结构与另外两者完全不同——它买到的是隔离性，付出的是边界伪影与请求级尾延迟。</p>\n<p>第二条对照轴是<strong>优化对象</strong>。特征缓存与块级跳步优化的是“算多少步”，潜空间一致性少步采样优化的是“步数上限”，DiT NVFP4 / FP8 系列优化的是“每步多快、多省显存”，CFG 批合并优化的是“条件分支的 batch 效率”。补丁调度不改变单步计算量，也不改变步数，它改变的是<strong>batch 的构成与 kernel 形状的规整度</strong>。因此它与量化、缓存类算法是正交的：可以在 NVFP4 量化的慢通道上再叠 patch 分级，也可以对快通道 patch 启用块级跳步。判断是否正交的标准很朴素——若两个算法的收益都来自同一资源（例如都靠减少 MMA 次数），叠加会互相吞掉收益；若一个省算力、一个改 batch 形状，叠加通常可加。</p>\n\n<h3 id=\"alg-mixed-res-serve-sec-48\">四十八 · 决策表：五类候选与适用条件</h3>\n<p>下表把同族候选压到可执行的判断维度上。“首选条件”一栏是选它的充分场景，“放弃信号”一栏出现任意一条就应换方案。表中不写具体数值，因为材料未给出批大小与 SLO 阈值，工程上应以实测的 patch 级 P99 与通道负载比来填。</p>\n<table class=\"mini\">\n<thead>\n<tr><th>候选算法</th><th>决策粒度</th><th>主要收益来源</th><th>首选条件</th><th>放弃信号</th></tr>\n</thead>\n<tbody>\n<tr><td>混合分辨率补丁调度</td><td>patch</td><td>batch 形状规整、大小请求隔离</td><td>高低分辨率混合负载，小请求 SLO 被长尾拖垮</td><td>请求分辨率单一；拼接开销占比高；尾延迟不可控</td></tr>\n<tr><td>请求级连续批处理 / 优先级调度</td><td>请求</td><td>调度器简单、无拼接</td><td>分辨率分布集中，batch 内张量形状接近</td><td>batch 被大请求拖慢，小请求 P99 恶化</td></tr>\n<tr><td>阶段级扩散服务流水</td><td>stage</td><td>DiT / VAE / 后处理重叠</td><td>VAE 解码与后处理占比可观，stage 间可并行</td><td>采样阶段内部仍是混 batch 瓶颈</td></tr>\n<tr><td>特征缓存与块级跳步</td><td>块 / 步</td><td>减少实际计算步数</td><td>相邻步特征高度相似，可容忍近似</td><td>高分辨率下缓存命中差、显存被缓存挤占</td></tr>\n<tr><td>NVFP4 / FP8 混合精度</td><td>算子</td><td>提升 MMA 吞吐、降显存带宽</td><td>Tensor Core 未饱和，显存带宽是瓶颈</td><td>数值敏感层多，量化误差不可接受</td></tr>\n</tbody>\n</table>\n<p>读表的方法是先定位瓶颈再选行。若 profile 显示 GPU 忙但 Tensor Core 利用率低、batch 内张量形状方差大，选补丁调度；若利用率已高而步数冗余，选缓存跳步；若单步 MMA 已饱和但显存带宽吃紧，选量化。补丁调度与量化可以同选，与请求级调度则是替代关系——两者都在争“谁来决定 batch 构成”，同时开启会让队列语义打架。</p>\n\n<h3 id=\"alg-mixed-res-serve-sec-49\">四十九 · 代价换算：什么时候 patch 化不划算</h3>\n<p>补丁调度的收益必须与两项新增代价对账。第一项是重叠 halo 带来的额外计算与显存：设原图高宽为 $H,W$，patch 尺寸 $h\\times w$，重叠边长为 $o$，则 patch 数约为 $\\lceil H/(h-o)\\rceil\\cdot\\lceil W/(w-o)\\rceil$，有效计算量放大约为</p>\n<div class=\"formula\">$$\\eta=\\frac{(h+o)(w+o)}{h\\cdot w}$$</div>\n<p>$\\eta$ 就是为消除接缝付出的算力税。$o$ 相对 $h,w$ 越大，接缝越少、税越重；$o$ 趋近于零则拼接处出现色彩断层。工程判断是：当 $\\eta$ 超过快慢通道分离带来的 Tensor Core 利用率增益时，patch 化净亏。第二项是请求级尾延迟：由给定公式，请求 SLO 等于所有 patch 中 queue 加 compute 的最大值，因此只要一个 patch 落进慢通道大 batch 的长队列，整个请求就被它拖住。这解释了为什么补丁调度必须配 SLO 标注——SLO 等级的作用不是排序好看，而是把“不能等的 patch”钉在快通道，防止慢通道的排队时间污染请求级尾延迟。</p>\n<p>具体例子：一个高分辨率请求切成若干 patch，其中大部分是高分辨率 patch 走慢通道，少数边缘 patch 因尺寸不足落进快通道。若调度器只看分辨率不看 SLO，边缘 patch 可能被塞进慢通道尾部，导致整个请求的完成时间由这个最小的 patch 决定——算力最少的 patch 反而成了关键路径。这是补丁调度最典型的反直觉失败，也是它与请求级调度最本质的区别：请求级调度里尾延迟由最大的请求决定，补丁调度里尾延迟可能由最小的 patch 决定。</p>\n\n<h3 id=\"alg-mixed-res-serve-sec-50\">五十 · 与阶段级流水的分工边界</h3>\n<p>阶段级扩散服务流水与补丁调度常被误认为二选一，实际是不同层的正交组合。阶段级流水把 DiT 采样、VAE 解码、后处理拆成可重叠的 stage，收益来自 stage 间并行与资源错峰；但它不改变采样阶段内部 batch 的构成，混 batch 的 kernel 形状问题原样保留。补丁调度恰好补这一层：它在采样 stage 内部把 patch 分流，使快通道的小 batch kernel 与慢通道的大 batch kernel 各自形状规整。组合时的接口是请求级缓冲区——patch 结果写回请求级缓冲区，全部 patch 完成后才进入拼接与 VAE 解码，因此 VAE stage 看到的是完整图像，与补丁调度无耦合。反过来，若把 VAE 也 patch 化，就与 VAE 分块并行解码重叠，属于重复设计。</p>\n<p>组合的代价落在显存上：重叠 patch 的中间激活、请求级缓冲区、以及慢通道大 batch 的激活峰值三者同时存在。部署时应把 patch 缓冲区与 KV / 激活预算分开核算，避免慢通道为了堆大 batch 而挤掉 patch 写回空间。一个可执行的判断是：若拼接与后处理的耗时占请求端到端时间的比例已经可观，说明补丁切分粒度太细，应放大 patch 尺寸、减少 patch 数，用更大的 $\\eta$ 换取更少的拼接次数与更简单的队列状态。</p>\n\n<h3 id=\"alg-mixed-res-serve-sec-51\">五十一 · 选择流程与切换信号</h3>\n<p>把选择写成可执行的判定序列，避免凭直觉选型。第一步看分辨率分布：若请求分辨率高度集中，batch 内张量形状本就接近，补丁调度的隔离收益接近零，直接选请求级连续批处理。第二步看小请求 SLO 是否被长尾拖垮：若小请求 P99 明显劣化而 GPU 利用率不高，说明 batch 被大请求拖慢，补丁调度是正解。第三步看单步计算是否已饱和：若 Tensor Core 利用率已高，补丁调度只能改善隔离、不能提升吞吐，此时应转向缓存跳步或量化。第四步对账 $\\eta$ 与拼接开销：若重叠税吃掉通道分离的增益，退回请求级调度并改用优先级队列保护小请求。</p>\n<p>运行期的切换信号同样要明确。快慢通道负载比持续失衡（一个通道排队、另一个空转）是补丁调度失效的前兆，此时应动态调整通道配额或把部分 patch 改派，而不是加大 batch。拼接处出现接缝与色彩断层，说明 halo 不足或融合后处理不当，应先加重叠再谈吞吐。请求级尾延迟的方差变大且与最大 patch 无关，说明尾延迟已被最小 patch 支配，需要检查 SLO 标注是否真正驱动了分通道。这三个信号对应三类失败模式，且都能在 patch 级指标上提前看到，不必等请求级 SLO 违约才反应。</p>\n<p>最后一条工程判断落在算法边界上：补丁调度解决的是“混合分辨率下的隔离与 kernel 规整”，它不解决“步数冗余”也不解决“单步太慢”。当 profile 显示瓶颈已经从 batch 构成转移到单步算力或显存带宽时，补丁调度应退居为隔离手段而非吞吐手段，把优化预算交给量化与缓存类算法；反之，当瓶颈是大小请求互相阻塞时，任何单步优化都无法替代 patch 级分流。这条边界决定了它在同族算法中的位置：不是更快的算法，而是把 GPU 资源按 patch 粒度重新匹配的调度算法。</p>\n\n<h3 id=\"alg-mixed-res-serve-sec-52\">五十二 · 分水岭不在算法本身，而在请求形状与尾延迟预算</h3>\n<p>把本方案放进同族算法谱系里，先要认清它换掉了哪个调度粒度。按请求整体调度的服务方案（连续批处理、请求级优先级队列）把一次 DiT 采样当作不可分割的调度单元，调度器看到的是“一个高分辨率请求占多少显存、跑多久”；扩散流水线分阶段服务把 DiT、VAE、后处理拆成 stage 分别排队，粒度落在阶段上；本方案把粒度压到 patch，在采样阶段内部按分辨率与 SLO 分流。三者的分界线是：谁能把长尾请求的计算量切成可独立排队的碎片。只有当一个高分辨率请求能被切成足够多、彼此可独立去噪的 patch 时，快通道的小请求才不会被它的大 batch 拖住；反之，若请求本身分辨率单一、或 patch 之间耦合极强（例如强全局一致性的结构约束），切分带来的收益立刻被拼接开销吃掉。选型的第一问不是“哪个算法更快”，而是“我的负载里高分辨率请求占比是否足以形成两条通道各自的稳定队列深度”——两条通道都填不满时，快通道退化为小 batch 低利用率的空转，慢通道则因排队过长把尾延迟推高，此时按请求整体调度反而更稳。</p>\n<p>代价可以用一条判据写清楚。patch 级调度的请求级完成时间由最慢 patch 支配，而切分本身要付重叠 halo 的算力与显存：</p>\n<div class=\"formula\">$$\\text{Cost}_{\\text{patch}} \\propto h\\cdot w\\cdot N_{\\text{step}},\\quad \\text{SLO}_{\\text{req}} = \\max_{p\\in\\text{patches}} \\left(T_{\\text{queue},p} + T_{\\text{compute},p}\\right)$$</div>\n<p>第二式说明尾延迟不是平均值问题：只要慢通道里有一个 patch 排在大 batch 后面，整个请求的 SLO 就被它拖垮，前面所有快通道 patch 提前完成都无济于事。因此本方案的适用条件必须包含“慢通道队列深度可控”——即高分辨率 patch 的到达率与慢通道大 batch 的服务率匹配，否则应退回请求级调度或对高分辨率请求单独限流。halo 重叠则直接放大第一式：重叠比例 r 使有效计算量按 (1+r) 量级上升，同时拼接缓冲区多占一份显存，这是切分粒度越细越不划算的根本原因，也是规模上限的来源。</p>\n<table class=\"mini\"><thead><tr><th>相邻方案</th><th>调度粒度</th><th>适用条件</th><th>失效条件</th></tr></thead><tbody><tr><td>请求级连续批处理</td><td>整请求</td><td>分辨率分布集中、请求数足以填满 batch</td><td>高低分辨率混跑，小请求被大请求拖成长尾</td></tr><tr><td>流水线分阶段服务</td><td>stage</td><td>阶段间资源需求差异大、可跨阶段重叠</td><td>单阶段内部仍是整请求，采样阶段的长尾未被拆解</td></tr><tr><td>本方案（patch 级分级）</td><td>patch</td><td>混合分辨率负载、小请求 SLO 易被长尾拖垮、慢通道队列可控</td><td>halo 开销压过收益、慢通道排队失控、拼接伪影不可接受</td></tr></tbody></table>\n<p>工程判断落在两个可观测信号上。其一是慢通道排队时延与快通道利用率的比值：快通道长期吃不饱而慢通道持续积压，说明分级阈值切错了，应把部分中等分辨率 patch 下放到快通道，或对高分辨率请求做准入控制；其二是拼接伪影的验收成本，若重叠 halo 与融合后处理带来的显存与算力开销使端到端吞吐回落到请求级调度之下，则本方案在该负载上不成立。反过来，当负载确实是高低分辨率混合、且小请求的 SLO 对尾延迟敏感时，patch 级分级是唯一能同时让两条通道各自保持规整 kernel 形状、又不互相阻塞的选项——它的边界不在算法能力，而在队列深度与 halo 预算这两笔账能否算平。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2025 · VAE 解码与潜空间压缩</td></tr><tr><td>解决什么</td><td>高分辨率请求的 DiT 计算量随像素平方增长，与低分辨率请求混跑时 GPU batch 被大请求拖慢，小请求 SLO …</td></tr><tr><td>一句话机制</td><td>把图像切成 patch，按 patch 分辨率与请求 SLO 分级调度：低分辨率 patch 走小 batch 快通道…</td></tr><tr><td>代价与失效</td><td>patch 切分与拼接引入边界伪影，需重叠 patch 与融合后处理，增加显存与算力；patch 级队列与拼接逻辑复杂，请求级尾延迟受最慢…</td></tr><tr><td>后继</td><td></td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-mixed-res-serve · 共 8 个片段</p>\n";break;}}})();
